/** All translations for zizhitongjian ch.006 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起柔兆敦牂，盡昭陽作噩，凡二十八年。", literal: "From Rouzhao Dunzang through Zhaoyang Zuoe; twenty-eight years in all.", idiomatic: "From Rouzhao Dunzang through Zhaoyang Zuoe—twenty-eight years in all." },
  { zh: "1河東守王稽坐與諸侯通，棄市。", literal: "1. Hedong grand administrator Wang Ji was convicted of communicating with the feudal lords and was executed in the marketplace.", idiomatic: "1. Wang Ji, grand administrator of Hedong, was convicted of dealing with the feudal lords and was executed in the marketplace." },
  { zh: "應侯日以不懌。", literal: "Day by day the Marquis of Rang grew displeased.", idiomatic: "Day by day the Marquis of Rang grew more uneasy." },
  { zh: "王臨朝而嘆，應侯請其故。", literal: "The king came to court and sighed; the Marquis of Rang asked the reason.", idiomatic: "The king came to court and sighed; the Marquis of Rang asked why." },
  { zh: "王曰：「今武安君死，而鄭安平、王稽等皆畔，內無良將而外多敵國，吾是以憂。", literal: "The king said: \"Now Lord Wuan is dead, and Zheng Anping, Wang Ji, and the rest have all turned rebel; within we have no worthy generals and without many enemy states—this is why I am troubled.\"", idiomatic: "The king said: \"Lord Wuan is dead, and Zheng Anping, Wang Ji, and the rest have all rebelled. Within we have no good generals; without, enemies press on every side. That is why I grieve.\"" },
  { zh: "」應侯懼，不知所出。", literal: "\" The Marquis of Rang was afraid and did not know what course to take.", idiomatic: "\" The Marquis of Rang was afraid and could see no way out." },
  { zh: "燕客蔡澤聞之，西入秦，先使人宣言於應侯曰：「蔡澤，天下雄辯之士。", literal: "A guest from Yan named Cai Ze heard of it, entered Qin from the west, and first sent someone to proclaim to the Marquis of Rang: \"Cai Ze is the most formidable debater under Heaven.\"", idiomatic: "Cai Ze, a guest from Yan, heard of this and went west into Qin. He first sent word to the Marquis of Rang: \"Cai Ze is the fiercest debater under Heaven.\"" },
  { zh: "彼見王，必困君而奪君之位。", literal: "When he sees the king, he will surely embarrass you and take your post.", idiomatic: "When he meets the king, he will corner you and steal your place.\"" },
  { zh: "」應侯怒，使人召之。", literal: "\" The Marquis of Rang was angry and sent someone to summon him.", idiomatic: "\" The Marquis of Rang was furious and sent for him." },
  { zh: "蔡澤見應侯，禮又倨。", literal: "When Cai Ze met the Marquis of Rang, his courtesy was again arrogant.", idiomatic: "When Cai Ze met the Marquis of Rang, his manner was again insolent." },
  { zh: "應侯不快，因讓之曰：「子宣言欲代我相，請聞其說。", literal: "The Marquis of Rang was displeased and reproved him, saying: \"You proclaimed that you wished to replace me as chancellor—let me hear your argument.\"", idiomatic: "The Marquis of Rang was displeased and rebuked him: \"You announced you meant to take my place as chancellor. Let me hear your case.\"" },
  { zh: "」蔡澤曰：「吁，君何見之晚也！", literal: "\" Cai Ze said: \"Alas, my lord, how late you see it!", idiomatic: "\" Cai Ze said: \"Ah—my lord, how late you see it!" },
  { zh: "夫四時之序，成功者去。", literal: "The sequence of the four seasons—when one has succeeded, one departs.", idiomatic: "The four seasons turn in order; when success is complete, it is time to go." },
  { zh: "君獨不見夫秦之商君、楚之吳起、越之大夫種，何足願與？", literal: "Have you alone not seen Qin's Lord Shang, Wu Qi of Chu, and the Grandee of Yue—how are they worth wishing to emulate?", idiomatic: "Have you not seen Qin's Lord Shang, Wu Qi of Chu, and the Grandee of Yue—why would you wish to end as they did?\"" },
  { zh: "」應侯謬曰：「何為不可？", literal: "\" The Marquis of Rang said in pretense: \"Why would it not be possible?", idiomatic: "\" The Marquis of Rang pretended not to understand: \"Why not?" },
  { zh: "此三子者，義之至也，忠之盡也。", literal: "These three men reached the utmost in righteousness and gave their all in loyalty.", idiomatic: "Those three reached the height of righteousness and gave their utmost in loyalty." },
  { zh: "君子有殺身以成名，死無所恨！", literal: "A gentleman may die to achieve fame and have no regret in death!", idiomatic: "A gentleman may give his life to win a name and die without regret!\"" },
  { zh: "」蔡澤曰：「夫人立功豈不期於成全邪？", literal: "\" Cai Ze said: \"When one establishes merit, does one not expect it to be brought to completion?", idiomatic: "\" Cai Ze said: \"When a man builds merit, does he not expect to see it through to the end?" },
  { zh: "身名俱全者，上也；", literal: "Body and name both preserved is the highest;", idiomatic: "To keep body and name intact—that is the highest;" },
  { zh: "名可法而身死者，次也；", literal: "name fit to be emulated though the body dies is second;", idiomatic: "to leave a name others may follow though the body perishes—that is second;" },
  { zh: "名僇辱而身全者，下也。", literal: "name shamed and disgraced though the body is preserved is lowest.", idiomatic: "to save the body while the name is shamed and disgraced—that is lowest." },
  { zh: "夫商君、吳起、大夫種，其為人臣盡忠致功，則可願矣。", literal: "Lord Shang, Wu Qi, and the Grandee—as ministers who exhausted loyalty and achieved merit—may be wished for.", idiomatic: "Lord Shang, Wu Qi, and the Grandee—as ministers who gave all their loyalty and won great merit—may be wished for." },
  { zh: "閎夭、周公，豈不亦忠且聖乎？", literal: "Are not Hong Yao and the Duke of Zhou likewise loyal and sage?", idiomatic: "Were not Hong Yao and the Duke of Zhou loyal and sage as well?" },
  { zh: "三子之可願，孰與閎夭、周公哉？", literal: "Which is more worth wishing for—the three men, or Hong Yao and the Duke of Zhou?", idiomatic: "Which is more worth wishing for—those three, or Hong Yao and the Duke of Zhou?\"" },
  { zh: "」應侯曰：「善。", literal: "\" The Marquis of Rang said: \"Well said.\"", idiomatic: "\" The Marquis of Rang said: \"You speak well.\"" },
  { zh: "」蔡澤曰：「然則君之主惇厚舊故，不倍功臣，孰與孝公、楚王、越王？", literal: "\" Cai Ze said: \"Then is your lord, who is sincere and thick toward old associates and does not betray merit-holders, the equal of Duke Xiao, the king of Chu, and the king of Yue?", idiomatic: "\" Cai Ze said: \"Then is your lord—so sincere with old friends, so faithful to men of merit—the equal of Duke Xiao, the king of Chu, and the king of Yue?\"" },
  { zh: "」曰：「未知何如。", literal: "\" He said: \"I do not yet know how he compares.\"", idiomatic: "\" He said: \"I cannot yet say how he compares.\"" },
  { zh: "」蔡澤曰：「君之功能孰與三子？", literal: "\" Cai Ze said: \"How does your merit compare with the three men's?\"", idiomatic: "\" Cai Ze said: \"How does your merit compare with theirs?\"" },
  { zh: "」曰：「不若。", literal: "\" He said: \"I do not match them.\"", idiomatic: "\" He said: \"I do not.\"" },
  { zh: "」蔡澤曰：「然則君身不退，患恐甚於三子矣。", literal: "\" Cai Ze said: \"Then if you do not withdraw while you still can, your peril may well exceed theirs.\"", idiomatic: "\" Cai Ze said: \"Then if you do not step down, your peril may be worse than theirs.\"" },
  { zh: "語曰：『日中則移，月滿則虧。", literal: "The saying goes: 'When the sun reaches noon it shifts; when the moon is full it wanes.", idiomatic: "As the proverb says: 'When the sun stands at noon it must move; when the moon is full it must wane." },
  { zh: "』進退嬴縮，與時變化，聖人之道也。", literal: "' Advance and retreat, expand and contract, changing with the times—this is the sage's way.", idiomatic: "' To advance and retreat, swell and shrink, changing with the times—that is the way of the sage." },
  { zh: "今君之怨已讎而德已報，意欲至矣而無變計，竊為君危之。", literal: "Now your enmities are revenged and your favors repaid; your desires have reached their limit yet you have no plan to change—I privately fear for you.", idiomatic: "Your enemies are already punished and your debts repaid; your desires are satisfied—yet you have no plan to change course. I fear for you." },
  { zh: "」應侯遂延以為上客，因薦於王。", literal: "\" The Marquis of Rang then received him as an honored guest and recommended him to the king.", idiomatic: "\" The Marquis of Rang then treated him as an honored guest and recommended him to the king." },
  { zh: "王召與語，大悅，拜為客卿。", literal: "The king summoned him for discourse, was greatly pleased, and appointed him Guest Minister.", idiomatic: "The king summoned him, spoke with him, was delighted, and made him Guest Minister." },
  { zh: "應侯因謝病免。", literal: "The Marquis of Rang thereupon claimed illness and resigned.", idiomatic: "The Marquis of Rang thereupon pleaded illness and resigned." },
  { zh: "王新悅蔡澤計畫，遂以為相國，澤為相數月，免。", literal: "The king, newly pleased with Cai Ze's plans, made him chancellor; Ze served as chancellor several months and was dismissed.", idiomatic: "The king, newly taken with Cai Ze's counsel, made him chancellor; Cai Ze held office only a few months before he was dismissed." },
  { zh: "2楚春申君以荀卿為蘭陵令。", literal: "2. Lord Chunshen of Chu made Xun Qing magistrate of Lanling.", idiomatic: "2. Lord Chunshen of Chu appointed Xun Qing magistrate of Lanling." },
  { zh: "荀卿者，趙人，名況，嘗與臨武君論兵於趙孝成王之前。", literal: "Xun Qing was a man of Zhao, named Kuang; he had once debated military affairs with Lord Linwu before King Xiaocheng of Zhao.", idiomatic: "Xun Qing—Xunzi—was from Zhao; his given name was Kuang. He had once debated warfare with Lord Linwu before King Xiaocheng of Zhao." },
  { zh: "王曰：「請問兵要。", literal: "The king said: \"I beg to ask the essentials of warfare.\"", idiomatic: "The king said: \"Tell me the essentials of warfare.\"" },
  { zh: "」臨武君對曰：「上得天時，下得地利，觀敵之變動，後之發，先之至，此用兵之要術也。", literal: "\" Lord Linwu replied: \"Above, gain Heaven's seasons; below, gain Earth's advantages; observe the enemy's shifts; strike after he moves yet arrive before him—this is the essential art of warfare.\"", idiomatic: "\" Lord Linwu answered: \"Win Heaven's seasons above and Earth's advantages below; watch how the enemy moves; move after he does yet arrive before him—that is the heart of war.\"" },
  { zh: "」荀卿曰：「不然。", literal: "\" Xun Qing said: \"Not so.\"", idiomatic: "\" Xunzi said: \"No.\"" },
  { zh: "臣所聞古之道，凡用兵攻戰之本，在乎一民。", literal: "The ancient way I have heard—in all warfare the root lies in unifying the people.", idiomatic: "The way I have heard from antiquity is this: in all attack and battle, the root lies in making the people one." },
  { zh: "弓矢不調，則羿不能以中；", literal: "If bow and arrow are not tuned, then Yi cannot hit the mark;", idiomatic: "If bow and arrow are not tuned, even Yi cannot hit the mark;" },
  { zh: "六馬不和，則造父不能以致遠；", literal: "if six horses are not in harmony, then Zaofu cannot reach far;", idiomatic: "if six horses do not pull as one, even Zaofu cannot run far;" },
  { zh: "士民不親附，則湯、武不能以必勝也。", literal: "if officers and people do not attach themselves in kinship, then Tang and Wu cannot be certain of victory.", idiomatic: "if soldiers and people do not stand with you, then not even Tang and Wu can be sure of victory." },
  { zh: "故善附民者，是乃善用兵者也。", literal: "Therefore one who is good at winning the people is one who is truly skilled in warfare.", idiomatic: "Whoever wins the people's hearts is the one who truly knows how to use arms." },
  { zh: "故兵要在乎附民而已。", literal: "Thus the essential of warfare lies in winning the people—nothing more.", idiomatic: "The essence of war is nothing but winning the people.\"" },
  { zh: "」臨武君曰：「不然。", literal: "\" Lord Linwu said: \"Not so.\"", idiomatic: "\" Lord Linwu said: \"No.\"" },
  { zh: "兵之所貴者勢利也，所行者變詐也。", literal: "What warfare prizes is advantage and gain; what it practices is shifting deception.", idiomatic: "What war values is advantage and profit; what it practices is shifting deceit." },
  { zh: "善用兵者感忽悠闇，莫知所從出。", literal: "Those skilled in war use confusion and darkness so no one knows whence they come.", idiomatic: "A master of war works in shadow and surprise until no one knows where he will strike." },
  { zh: "孫吳用之，無敵於天下，豈必待附民哉！", literal: "Sun and Wu employed these and were unmatched under Heaven—must one really wait to win the people!", idiomatic: "Sun Wu used such methods and was unmatched under Heaven—must one really wait on winning the people?\"" },
  { zh: "」荀卿曰：「不然。", literal: "\" Xun Qing said: \"Not so.\"", idiomatic: "\" Xunzi said: \"No.\"" },
  { zh: "臣之所道，仁人之兵，王者之志也。", literal: "What I speak of is the army of the benevolent man, the will of the true king.", idiomatic: "What I speak of is the army of a benevolent man—the mind of a true king." },
  { zh: "君之所貴，權謀勢利也。", literal: "What you prize is scheming power and advantage.", idiomatic: "What you prize is cunning, power, and gain." },
  { zh: "仁人之兵，不可詐也。", literal: "The army of the benevolent man cannot be deceived.", idiomatic: "The army of a benevolent man cannot be deceived." },
  { zh: "彼可詐者，怠慢者也，露袒者也，君臣上下之間滑然有離德者也。", literal: "Those who can be deceived are the negligent, the exposed, those between ruler and minister and high and low who are slickly estranged in virtue.", idiomatic: "Only the slack, the careless, the nakedly exposed—armies where ruler and minister and high and low slide apart in spirit—can be deceived." },
  { zh: "故以桀詐桀，猶巧拙有幸焉。", literal: "Therefore to use Jie to deceive Jie still leaves room for luck between skill and clumsiness.", idiomatic: "To pit Jie's cunning against Jie's may still leave room for luck between the clever and the clumsy." },
  { zh: "以桀詐堯，譬之以卵投石，以指橈沸，若赴水火，入焉焦沒耳。", literal: "To use Jie to deceive Yao is like hurling eggs at stone, stirring boiling water with a finger, or rushing into fire and water—to enter is only to be burned and drowned.", idiomatic: "To pit Jie's cunning against Yao's is like throwing eggs at stone, stirring boiling water with a finger, or hurling oneself into fire and flood—you enter only to be burned and drowned." },
  { zh: "故仁人之兵，上下一心，三軍同力。", literal: "Therefore the army of the benevolent man is of one mind above and below; the three armies share one strength.", idiomatic: "The army of a benevolent man is of one mind from top to bottom; the three hosts fight as one." },
  { zh: "臣之於君也，下之於上也，若子之事父，弟之事兄，若手臂之扞頭目而覆胸腹也。", literal: "Ministers toward the ruler, inferiors toward superiors—like sons serving fathers, younger brothers serving elder brothers; like arms shielding the head and covering the chest and belly.", idiomatic: "Ministers toward their ruler, men toward their superiors—they serve as sons serve fathers, younger brothers serve elder brothers; they are like arms that shield the head and cover the chest and belly." },
  { zh: "詐而襲之，與先驚而後擊之，一也。", literal: "To deceive and attack them is the same as to alarm them first and strike them afterward.", idiomatic: "To deceive and strike them is no different from alarming them first and hitting them afterward." },
  { zh: "且仁人用十里之國則將有百里之聽，用百里之國則將有千里之聽，用千里之國則將有四海之聽，必將聰明警戒，和傅而一。", literal: "Moreover, when the benevolent man uses a state of ten li he will have listeners for a hundred li; using a hundred-li state he will have listeners for a thousand li; using a thousand-li state he will have listeners throughout the four seas—he is sure to be bright, vigilant, and harmoniously bound as one.", idiomatic: "When a benevolent ruler holds a state of ten li, his reach of counsel extends a hundred; with a hundred li, a thousand; with a thousand li, the four seas. He is alert, watchful, harmoniously knit as one." },
  { zh: "故仁人之兵，聚則成卒，散則成列，延則若莫耶之長刃，嬰之者斷；", literal: "Therefore the army of the benevolent man, gathered, forms a host; scattered, forms ranks; extended, is like the long blade of Moye—who touches it is cut;", idiomatic: "The army of a benevolent man, massed, becomes an army; dispersed, ordered ranks; drawn out, is like the long edge of a Moye blade—touch it and you are cut;" },
  { zh: "兌則若莫耶之利鋒，當之者潰。", literal: "concentrated, is like Moye's sharp point—who blocks it is routed.", idiomatic: "concentrated, like Moye's keen point—meet it and you break." },
  { zh: "圜居而方止，則若盤石然，觸之者角摧而退耳。", literal: "Encamped in circle and halting in square, it is like bedrock; who touches it has his horns broken and retreats.", idiomatic: "Camped in circle, halted in square, it stands like bedrock; whoever strikes it breaks his horns and falls back." },
  { zh: "且夫暴國之君，將誰與至哉？", literal: "Moreover, the ruler of a violent state—whom will he bring with him?", idiomatic: "And whom will the ruler of a cruel state bring with him?" },
  { zh: "彼其所與至者，必其民也。", literal: "Those he brings with him will surely be his own people.", idiomatic: "Only his own people will come." },
  { zh: "其民之親我歡若父母，其好我芬若椒蘭；", literal: "His people love us as gladly as parents; they delight in us fragrant as pepper and orchid;", idiomatic: "His people will love us as they love their parents, delight in us as in pepper and orchid;" },
  { zh: "彼反顧其上則若灼黥，若仇讎；", literal: "when they turn back and look on their ruler he is like a seared brand, like an enemy;", idiomatic: "but when they look back at their ruler he seems a seared brand, an enemy;" },
  { zh: "人之情，雖桀、跖，豈有肯為其所惡，賊其所好者哉！", literal: "in human nature, even Jie or Robber Zhi—would they be willing to serve what they hate and strike down what they love!", idiomatic: "in human nature—even Jie or Robber Zhi—who would serve what he hates and strike down what he loves?" },
  { zh: "是猶使人之子孫自賊其父母也。", literal: "This is like making a man's sons and grandsons strike down their own parents.", idiomatic: "That would be like asking sons and grandsons to kill their own parents." },
  { zh: "彼必將來告〔之〕<ref>彼必將來告〔之〕章校「十二行本『告』下有『之』字；", literal: "They are sure to come and report [it]<ref>They are sure to come and report [it]—Zhang's collation: in the twelve-line edition below \"report\" there is the character \"it\";", idiomatic: "They are sure to come and report [it]<ref>\"They are sure to come and report [it]\"—Zhang's collation: the twelve-line edition has the character \"it\" below \"report\";" },
  { zh: "乙十一行本同；", literal: "the Y eleven-line edition agrees;", idiomatic: "the Y eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "退齋校同。", literal: "Tuizhai's collation agrees.", idiomatic: "Tuizhai's collation agrees." },
  { zh: "」，《荀子》正有「之」字，據補。", literal: "\" The Xunzi indeed has the character \"it\"; supplemented accordingly.", idiomatic: "\" The Xunzi has the character \"it\"; it is supplied here." },
  { zh: "</ref>，夫又何可詐也！", literal: "</ref>—how then could they be deceived!", idiomatic: "</ref>—how then could such an army be deceived?" },
  { zh: "故仁人用國日明，諸侯先順者安，後順者危，敵之者削，反之者亡。", literal: "Therefore when the benevolent man uses his state, day by day it grows bright; among feudal lords, those who submit first are secure, those who submit late are in peril, those who oppose are diminished, those who turn against him perish.", idiomatic: "When a benevolent ruler governs, his state grows brighter day by day. Among the feudal lords, those who yield first are safe, those who yield late are in danger, those who resist are cut down, those who turn away perish." },
  { zh: "《詩》曰：『武王載發，有虔秉鉞，如火烈烈，則莫我敢遏，』此之謂也。", literal: "The Book of Songs says: 'King Wu set forth; reverently he grasped the battle-axe; blazing like fire—none dared bar our way'—this is what is meant.", idiomatic: "The Book of Songs says: 'King Wu marched forth, reverently bearing the battle-axe; blazing like fire—none dared stand in our way.' This is what is meant.\"" },
  { zh: "孝成王、臨武君曰：「善。", literal: "King Xiaocheng and Lord Linwu said: \"Well said.\"", idiomatic: "King Xiaocheng and Lord Linwu said: \"Well spoken.\"" },
  { zh: "請問王者之兵，設何道，何行而可？", literal: "We beg to ask: for the army of a true king, what Way should be established, what conduct will suffice?", idiomatic: "Tell us: for the army of a true king, what Way must be set up, what conduct will do?\"" },
  { zh: "」荀卿曰：「凡君賢者其國治，君不能者其國亂；", literal: "\" Xun Qing said: \"Wherever the ruler is worthy the state is governed; where the ruler is incapable the state is in disorder;", idiomatic: "\" Xunzi said: \"Where the ruler is worthy the state is well governed; where he is not, it falls into disorder;" },
  { zh: "隆禮貴義者其國治，簡禮賤義者其國亂。", literal: "where ritual is exalted and righteousness honored the state is governed; where ritual is slighted and righteousness despised the state is in disorder.", idiomatic: "where ritual is honored and righteousness prized, the state is governed; where ritual is slighted and righteousness cheapened, it is in disorder." },
  { zh: "治者強，亂者弱，是強弱之本也。", literal: "The governed are strong, the disordered weak—this is the root of strength and weakness.", idiomatic: "Order brings strength, disorder weakness—that is the root of power and weakness." },
  { zh: "上足卬則下可用也，上不足卬則下不可用也。", literal: "When those above have enough to support themselves, those below can be employed; when those above lack enough to support themselves, those below cannot be employed.", idiomatic: "When those above have enough to stand on their own, those below can be used; when those above cannot stand, those below cannot be used." },
  { zh: "下可用則強，下不可用則弱，是強弱之常也。", literal: "When those below can be employed the state is strong; when they cannot, weak—this is the constant of strength and weakness.", idiomatic: "When the lower ranks can be relied on, the state is strong; when they cannot, it is weak—such is the law of strength and weakness." },
  { zh: "〔好士者強，不好士者弱；", literal: "[One who loves scholars is strong; one who does not love scholars is weak;", idiomatic: "[One who values scholars is strong; one who does not is weak;" },
  { zh: "愛民者強，不愛民者弱；", literal: "one who loves the people is strong; one who does not love the people is weak;", idiomatic: "one who loves the people is strong; one who does not is weak;" },
  { zh: "政令信者強，政令不信者弱；", literal: "where government orders are trusted the state is strong; where government orders are not trusted it is weak;", idiomatic: "where edicts are trusted the state is strong; where they are not, it is weak;" },
  { zh: "重用兵者強，輕用兵者弱；", literal: "one who values warfare is strong; one who lightly uses warfare is weak;", idiomatic: "one who values arms is strong; one who treats war lightly is weak;" },
  { zh: "權出一者強，權出二者弱；", literal: "where authority issues from one source the state is strong; where authority issues from two it is weak;", idiomatic: "where power rests in one hand the state is strong; where it is divided, it is weak;" },
  { zh: "是強弱之常也〕<ref>〔好士者強……是強弱之常也〕章校「十二行本『齊』上有『好士者強……是強弱之常也』五十五字；", literal: "this is the constant of strength and weakness]<ref>[One who loves scholars is strong... this is the constant of strength and weakness]—Zhang's collation: in the twelve-line edition above \"Qi\" there are fifty-five characters \"One who loves scholars is strong... this is the constant of strength and weakness\";", idiomatic: "such is the law of strength and weakness]<ref>[One who values scholars is strong... such is the law of strength and weakness]—Zhang's collation: the twelve-line edition has fifty-five characters above \"Qi\": \"One who values scholars is strong... such is the law of strength and weakness\";" },
  { zh: "乙十一行本同；", literal: "the Y eleven-line edition agrees;", idiomatic: "the Y eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同；", literal: "Zhang's collation agrees;", idiomatic: "Zhang's collation agrees;" },
  { zh: "退齋校同。", literal: "Tuizhai's collation agrees.", idiomatic: "Tuizhai's collation agrees." },
  { zh: "」，《荀子》正有此五十五字，據補。", literal: "\" The Xunzi indeed has these fifty-five characters; supplemented accordingly.", idiomatic: "\" The Xunzi has these fifty-five characters; they are supplied here." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "齊人隆技擊，其技也，得一首者則賜贖錙金，無本賞矣。", literal: "The men of Qi exalt fighting skill; in their contests, whoever takes one head is given gold to redeem a half-ounce—there is no reward for the root.", idiomatic: "The men of Qi prize fighting skill: in their contests, whoever takes a head wins gold worth half an ounce, but there is no reward for the foundation itself." },
  { zh: "是事小敵毳，則偷可用也；", literal: "When the affair is small and the enemy weak and fluffy, then the thief-type [troops] can be used;", idiomatic: "When the task is small and the enemy weak, then mercenary raiders will do;" },
  { zh: "事大敵堅，則渙焉離耳。", literal: "when the affair is great and the enemy firm, then they scatter and disperse.", idiomatic: "when the task is great and the enemy tough, they scatter and melt away." },
  { zh: "若飛鳥然，傾側反覆無日，是亡國之兵也，兵莫弱是矣，是其去賃市傭而戰之幾矣。", literal: "Like birds, tipping and turning without a fixed day—this is the army of a perishing state; no army is weaker than this; it differs little from hired laborers from the rental market going to battle.", idiomatic: "Like birds, wheeling and veering with no fixed course—this is the army of a doomed state; no army is feebler; it differs little from day-laborers hired at the market going off to fight." },
  { zh: "魏氏之武卒，以度取之；", literal: "Wei’s martial militia are taken by measurement;", idiomatic: "Wei’s crack infantry are recruited by bodily measure;" },
  { zh: "衣三屬之甲，操十二石之弩，負矢五十個，置戈其上，冠冑帶劍，贏二日之糧，日中而趨百里；", literal: "they wear triple-layered armor, wield twelve-stone crossbows, carry fifty arrows, set halberds atop [the pack], don helmets and gird swords, bear two days’ rations, and by midday can hurry a hundred li;", idiomatic: "they wear triple-layer armor, wield twelve-stone crossbows, carry fifty arrows, set halberds on the load, don helmet and sword, bear two days’ rations, and by noon can march a hundred li;" },
  { zh: "中試則復其戶，利其田宅。", literal: "pass the examination and their household is exempted from corvée, their fields and dwellings favored.", idiomatic: "pass the trial and their household is exempt from service and their land and home favored." },
  { zh: "是其氣力數年而衰，而復利未可奪也，改造則不易周也，是故地雖大，其稅必寡，是危國之兵也。", literal: "Thus their strength declines within a few years, yet the benefits granted cannot be taken back; to reorganize them is not easy to carry through—hence though the territory is large, its tax revenue must be sparse: this is the army of a state in peril.", idiomatic: "Their strength fades in a few years, yet the privileges granted cannot be revoked; reshaping them cannot be done overnight—so though the land is vast, tax revenue must run thin: this is the army of a state in danger." },
  { zh: "秦人，其生民也狹隘，其使民也酷烈，劫之以勢，隱之以厄，忸之以慶賞，鰌之以刑罰，使民所以要利於上者，非鬬無由也。", literal: "As for the people of Qin, their livelihood is narrow; their employment of the people is harsh and fierce—coerced by power, trapped in straits, enticed by rewards and punishments, driven by penalties and fines, so that for the people to seek essential profit from their superiors there is no way except fighting.", idiomatic: "The people of Qin live in straitened circumstances; their rulers use them harshly—coerced by power, cornered in distress, baited with rewards and punishments, prodded with penalties—so that to win what they need from above they have no recourse but battle." },
  { zh: "使以功賞相長，五甲首而隸五家，是最為眾強長久之道。", literal: "They cause merit and reward to advance together; five [enemy] heads in armor enslave five households—this is the way most numerous, strong, and lasting.", idiomatic: "They link merit to reward: five armored heads [taken] bind five households as dependents—this is the way to mass strength that lasts." },
  { zh: "故四世有勝，非幸也，數也。", literal: "Hence four generations of victory—this is not luck but necessity.", idiomatic: "Hence four generations of victory—not fortune but the natural course of things." },
  { zh: "故齊之技擊不可以遇魏之武卒，魏之武卒不可以遇秦之銳士，秦之銳士不可以當桓、文之節制，桓、文之節制不可以當湯、武之仁義，有遇之者，若以焦熬投石焉。", literal: "Thus Qi’s assault troops cannot face Wei’s martial militia; Wei’s martial militia cannot face Qin’s elite soldiers; Qin’s elite soldiers cannot withstand the regulation of Duke Huan and Duke Wen; the regulation of Duke Huan and Duke Wen cannot withstand the benevolence and righteousness of Tang and Wu—whoever meets these latter, it is like pouring rich broth upon stone.", idiomatic: "Qi’s prize-fighters cannot stand against Wei’s crack infantry; Wei’s crack infantry cannot stand against Qin’s shock troops; Qin’s shock troops cannot match the disciplined hosts of Duke Huan and Duke Wen; Duke Huan and Duke Wen’s hosts cannot match the benevolent armies of Tang and Wu—whoever meets the latter, it is like pouring broth on stone." },
  { zh: "兼是數國者，皆干賞蹈利之兵也，傭徒鬻賣之道也，未有貴上安制綦節之理也。", literal: "All these several states alike are armies that seek rewards and chase profit—the way of hired laborers and peddlers; they have never possessed the principle of honoring superiors, securing control, and utmost regulation.", idiomatic: "All these states alike field armies that chase pay and profit—the way of hired hands and hucksters; they know nothing of honoring superiors, secure command, and true discipline." },
  { zh: "諸侯有能微妙之以節，則作而兼殆之耳。", literal: "If any feudal lord can subtly apply regulation to them, he will rise and in time annex and endanger them.", idiomatic: "Any lord who can subtly bring regulation to bear on them will rise and in time swallow and endanger them." },
  { zh: "故招延募選，隆勢詐，尚功利，是漸之也。", literal: "Hence recruiting and extending, enlisting and selecting, exalting power and fraud, and honoring utility and profit—this is to be gradually overcome.", idiomatic: "Hence recruiting widely, exalting stratagem and fraud, and honoring utility and profit—this is to be worn down step by step." },
  { zh: "禮義教化，是齊之也。", literal: "Ritual, righteousness, teaching, and transformation—this is to be brought into alignment.", idiomatic: "Ritual, righteousness, teaching, and transformation—this is to bring them into order." },
  { zh: "故以詐遇詐，猶有巧拙焉；", literal: "Hence when fraud meets fraud, there is still skill and clumsiness;", idiomatic: "When fraud meets fraud, one side may still outdo the other;" },
  { zh: "以詐遇齊，譬之猶以錐刀墮太山也。", literal: "when fraud meets alignment, it is like trying to fell Mount Tai with an awl or knife.", idiomatic: "when fraud meets disciplined order, it is like trying to topple Mount Tai with an awl." },
  { zh: "故湯、武之誅桀、紂也，拱挹指麾，而強暴之國莫不趨使，誅桀、紂若誅獨夫。", literal: "Hence when Tang and Wu punished Jie and Zhou, with folded hands they gestured and commanded, and no violent state failed to hurry to serve them; punishing Jie and Zhou was like punishing lone miscreants.", idiomatic: "When Tang and Wu punished Jie and Zhou, with folded hands they directed their hosts, and every tyrannical state hastened to obey; punishing Jie and Zhou was like executing lone criminals." },
  { zh: "故《泰誓》曰：『獨夫紂，』此之謂也。", literal: "Hence the “Great Oath” says: ‘Lone miscreant Zhou’—this is what is meant.", idiomatic: "Hence the Great Oath says, ‘The lone miscreant Zhou’—this is what is meant." },
  { zh: "故兵大齊則制天下，小齊則治鄰敵。", literal: "Hence when the army is greatly aligned it controls all under Heaven; when slightly aligned it governs neighboring foes.", idiomatic: "When an army is fully aligned it masters the realm; when partly aligned it masters neighboring foes." },
  { zh: "若夫招延募選，隆勢詐，尚功利之兵，則勝不勝無常，代翕代張，代存代亡，相為雌雄耳。", literal: "As for armies that recruit and extend, enlist and select, exalt power and fraud, and honor utility and profit—victory and defeat have no constancy; now contracting, now expanding, now surviving, now perishing—they merely take turns as male and female.", idiomatic: "As for armies built on recruiting, stratagem, and profit—victory and defeat never settle; they wax and wane, live and die by turns, merely swapping roles as victor and vanquished." },
  { zh: "夫是之謂盜兵，君子不由也。", literal: "This is what is called bandit-armies; the gentleman does not follow them.", idiomatic: "These are called bandit-armies; the gentleman does not rely on them." },
  { zh: "孝成王、臨武君曰：「善。", literal: "King Xiaocheng and Lord Linwu said: “Good.", idiomatic: "King Xiaocheng and Lord Linwu said: “Excellent." },
  { zh: "請問為將。", literal: "We ask about being a general.", idiomatic: "We ask about commanding as a general." },
  { zh: "」荀卿曰：「知莫大乎棄疑，行莫大乎無過，事莫大乎無悔。", literal: "” Master Xun said: “In knowledge nothing is greater than abandoning doubt; in conduct nothing is greater than having no faults; in affairs nothing is greater than having no regrets.", idiomatic: "” Master Xun said: “In knowledge nothing surpasses casting off doubt; in conduct nothing surpasses avoiding fault; in affairs nothing surpasses leaving no regrets." },
  { zh: "事至無悔而止矣，不可必也。", literal: "When affairs reach the point of no regret, stop there—one cannot insist on certainty.", idiomatic: "When affairs reach the point of no regret, stop there; certainty is not attainable." },
  { zh: "故制號政令，欲嚴以威；", literal: "Hence in establishing designations and government orders, one wishes them strict so as to inspire awe;", idiomatic: "In issuing commands and orders, make them strict to inspire awe;" },
  { zh: "慶賞刑罰，欲必以信；", literal: "in rewards and punishments, one wishes them certain through trustworthiness;", idiomatic: "in rewards and punishments, make them certain through good faith;" },
  { zh: "處舍收藏，欲周以固；", literal: "in quarters, stores, and reserves, one wishes them comprehensive and secure;", idiomatic: "in quarters, stores, and reserves, make them thorough and secure;" },
  { zh: "徙舉進退，欲安以重，欲疾以速；", literal: "in movements, deployments, advances, and retreats, one wishes them settled and weighty, yet swift when speed is needed;", idiomatic: "in marching, deploying, advancing, and retreating, make them steady and weighty, yet swift when speed is needed;" },
  { zh: "窺敵觀變，欲潛以深，欲伍以參；", literal: "in spying on the enemy and observing changes, one wishes concealment deep, and deployment in files of three and five;", idiomatic: "in scouting the enemy and reading changes, keep hidden and deep, and array scouts in threes and fives;" },
  { zh: "遇敵決戰，必行吾所明，無行吾所疑；", literal: "when meeting the enemy and deciding battle, one must execute what one has made clear, and not execute what one doubts;", idiomatic: "when meeting the enemy in decisive battle, execute what you have made clear; do not execute what you doubt;" },
  { zh: "夫是之謂六術。", literal: "this is what is called the six arts.", idiomatic: "these are called the six arts." },
  { zh: "無欲將而惡廢，無怠勝而忘敗，無威內而輕外，無見其利而不顧其害，凡慮事欲熟而用財欲泰，夫是之謂五權。", literal: "Do not desire command yet hate dismissal; do not grow slack in victory and forget defeat; do not awe those within yet slight those without; do not see the profit and disregard the harm; in all deliberation wish thoroughness, in using wealth wish sufficiency—this is what is called the five balances.", idiomatic: "Do not crave command yet hate removal; do not grow slack in victory and forget defeat; do not awe your own side yet slight outsiders; do not see gain and ignore harm; in all planning be thorough, in spending be ample—these are the five balances." },
  { zh: "將所以不受命於主有三，可殺而不可使處不完，可殺而不可使擊不勝，可殺而不可使欺百姓，夫是之謂三至。", literal: "There are three reasons a general may refuse orders from his ruler: he may be executed, yet one cannot make him garrison an incomplete position; he may be executed, yet one cannot make him attack when victory is impossible; he may be executed, yet one cannot make him deceive the common people—this is what is called the three ultimates.", idiomatic: "There are three cases in which a general may refuse his ruler’s orders: he may be killed, yet cannot be made to hold an untenable post; he may be killed, yet cannot be made to attack when victory is impossible; he may be killed, yet cannot be made to cheat the people—these are the three ultimates." },
  { zh: "凡受命於主而行三軍，三軍既定，百官得序，群物皆正，則主不能喜，敵不能怒，夫是之謂至臣。", literal: "Whenever one receives orders from the ruler and leads the three armies—once the three armies are settled, the hundred officers find their places, and all things are set right—then the ruler cannot [unduly] rejoice and the enemy cannot [easily] rage: this is what is called the consummate minister.", idiomatic: "Whoever receives his ruler’s commission and leads the three armies—once the armies are settled, officers in order, and all things aligned—neither the ruler’s favor nor the enemy’s wrath can sway him: this is the consummate servant." },
  { zh: "慮必先事而申之以敬，慎終如始，始終如一，夫是之謂大吉。", literal: "In deliberation one must anticipate affairs and extend them with reverence; be careful at the end as at the beginning, beginning and end as one—this is what is called great good fortune.", idiomatic: "In planning anticipate events and carry them through with reverence; be as careful at the end as at the start, consistent from first to last—this is called great good fortune." },
  { zh: "凡百事之成也必在敬之，其敗也必在慢之。", literal: "In all hundred affairs, success must lie in reverence; failure must lie in negligence.", idiomatic: "In all affairs success rests on reverence; failure rests on negligence." },
  { zh: "故敬勝怠則吉，怠勝敬則滅；", literal: "Hence when reverence conquers negligence there is good fortune; when negligence conquers reverence there is ruin;", idiomatic: "When reverence conquers negligence, good fortune follows; when negligence conquers reverence, ruin follows;" },
  { zh: "計勝欲則從，欲勝計則兇。", literal: "when planning conquers desire one follows it; when desire conquers planning there is disaster.", idiomatic: "when planning conquers appetite, follow it; when appetite conquers planning, disaster." },
  { zh: "戰如守，行如戰，有功如幸。", literal: "Fight as though defending; march as though fighting; treat achievement as though accidental.", idiomatic: "Fight as in a siege; march as in battle; treat success as undeserved luck." },
  { zh: "敬謀無曠，敬事無曠，敬吏無曠，敬眾無曠，敬敵無曠，夫是之謂五無曠。", literal: "Reverent in planning without neglect, reverent in affairs without neglect, reverent toward officers without neglect, reverent toward the masses without neglect, reverent toward the enemy without neglect—this is what is called the five without neglect.", idiomatic: "Reverent in planning without slackness, in affairs without slackness, toward officers without slackness, toward the troops without slackness, toward the enemy without slackness—these are the five without neglect." },
  { zh: "慎行此六術、五權、三至，而處之以恭敬、無曠，夫是之謂天下之將，則通於神明矣。", literal: "Carefully practice these six arts, five balances, and three ultimates, and comport yourself with reverence and without neglect—this is what is called a general of all under Heaven; then you will penetrate to the spirit-like.", idiomatic: "Practice these six arts, five balances, and three ultimates carefully, and comport yourself with reverence and without neglect—then you are a general of all under Heaven and commune with the divine." },
  { zh: "臨武君曰：「善。", literal: "Lord Linwu said: “Good.", idiomatic: "Lord Linwu said: “Excellent." },
  { zh: "請問王者之軍制。", literal: "We ask about the military institutions of a true king.", idiomatic: "We ask about the military institutions of a true king." },
  { zh: "」荀卿曰：「將死鼓，御死轡，百吏死職，〔士〕(", literal: "” Master Xun said: “The general dies [at his] drum, the charioteer dies [at his] reins, the hundred officers die at their posts, [the officer] (", idiomatic: "” Master Xun said: “The general dies at his drum, the charioteer at his reins, the hundred officers at their posts, [the officer] (" },
  { zh: "上)", literal: "superior)", idiomatic: "superior)" },
  { zh: "大夫死行列<ref>〔士〕(", literal: "the grand officer dies in rank and file<ref>[the officer] (", idiomatic: "the grand officer dies in rank and file<ref>[the officer] (" },
  { zh: "上)", literal: "superior)", idiomatic: "superior)" },
  { zh: "大夫死行列據《荀子·議兵篇》改。", literal: "the grand officer dies in rank and file—emended per “On Military Affairs” in the Xunzi.", idiomatic: "the grand officer dies in rank and file—emended per “On Military Affairs” in the Xunzi." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "聞鼓聲而進，聞金聲而退。", literal: "Hearing the drum, advance; hearing the gong, withdraw.", idiomatic: "At the drum, advance; at the gong, withdraw." },
  { zh: "順命為上，有功次之。", literal: "Obeying orders is primary; merit is secondary.", idiomatic: "Obedience comes first; merit second." },
  { zh: "令不進而進，猶令不退而退也，其罪惟均。", literal: "To advance when ordered not to advance is like withdrawing when ordered not to withdraw—the crime is equally judged.", idiomatic: "To advance when ordered not to advance is like retreating when ordered not to retreat—the penalty is the same." },
  { zh: "不殺老弱，不獵禾稼，服者不禽，格者不赦，奔命者不獲。", literal: "Do not kill the old and weak; do not hunt down grain crops; those who submit are not captured; those who resist are not pardoned; those who flee on urgent orders are not pursued.", idiomatic: "Do not kill the old and weak; do not trample the crops; those who yield are not taken prisoner; those who resist are not spared; those fleeing on urgent orders are not pursued." },
  { zh: "凡誅，非誅其百姓也，誅其亂百姓者也。", literal: "In all punishment, one does not punish the common people—one punishes those who disorder the common people.", idiomatic: "In all punitive campaigns, the aim is not to punish the people but those who make the people rebel." },
  { zh: "百姓有捍其賊，則是亦賊也。", literal: "If the common people defend their tyrant, then they too are tyrants.", idiomatic: "If the people defend a tyrant, they too are tyrants." },
  { zh: "以〔故〕(", literal: "Those who [therefore] (", idiomatic: "Those who [therefore] (" },
  { zh: "其)", literal: "comply)", idiomatic: "comply)" },
  { zh: "順刃者生<ref>以〔故〕(", literal: "who yield to the blade live<ref>Those who [therefore] (", idiomatic: "who yield to the blade live<ref>Those who [therefore] (" },
  { zh: "其)", literal: "comply)", idiomatic: "comply)" },
  { zh: "順刃者生據《荀子·議兵篇》改。", literal: "who yield to the blade live—emended per “On Military Affairs” in the Xunzi.", idiomatic: "who yield to the blade live—emended per “On Military Affairs” in the Xunzi." },
  { zh: "</ref>，傃刃者死，奔命者貢。", literal: "</ref>; those who face the blade die; those who flee on urgent orders present themselves.", idiomatic: "</ref>; those who face the blade die; those who flee on urgent orders come forward of themselves." },
  { zh: "微子〔啟〕(", literal: "Prince Weizi [Qi] (", idiomatic: "Prince Weizi [Qi] (" },
  { zh: "開)", literal: "Kai)", idiomatic: "Kai)" },
  { zh: "封於宋<ref>微子〔啟〕(", literal: "was enfeoffed in Song<ref>Prince Weizi [Qi] (", idiomatic: "was enfeoffed in Song<ref>Prince Weizi [Qi] (" },
  { zh: "開)", literal: "Kai)", idiomatic: "Kai)" },
  { zh: "封於宋此處《荀子》原文避漢諱，今改正。", literal: "was enfeoffed in Song—here the original text of the Xunzi avoided Han taboo; now corrected.", idiomatic: "was enfeoffed in Song—here the original Xunzi text avoided Han taboo; now corrected." },
  { zh: "</ref>，曹觸龍斷於軍，商之服民，所以養生之者無異周人，故近者歌謳而樂之，遠者竭蹶而趨之，無幽閒辟陋之國，莫不趨使而安樂之，四海之內若一家，通達之屬莫不從服，夫是之謂人師。", literal: "</ref>; Cao Chu Long was executed in the army; in how the people of Shang were governed, the means of sustaining life were no different from the Zhou people—hence those near sang and rejoiced, those far strained every limb to hurry to them; no remote, secluded, or crude state failed to hurry to serve and find peace and joy; within the four seas it was like one household, and all connected domains none failed to follow and submit—this is what is called a teacher of men.", idiomatic: "</ref>; Cao Chu Long was put to death in the army; in how the people of Shang were ruled, the means of sustaining life were no different from the Zhou—so those near sang for joy, those far hurried with all their strength; no remote or crude state failed to hasten to serve and find peace; within the four seas it was one household, and every connected domain submitted—this is called a teacher of mankind." },
  { zh: "《詩》曰：『自西自東，自南自北，無思不服。", literal: "The Odes says: ‘From west and east, from south and north, none failed to submit.", idiomatic: "The Odes says, ‘From west and east, from south and north, none failed to submit." },
  { zh: "』此之謂也。", literal: "’ This is what is meant.", idiomatic: "’ This is what is meant." },
  { zh: "王者有誅而無戰，城守不攻，兵格不擊，敵上下相喜則慶之，不屠城，不潛軍，不留眾，師不越時，故亂者樂其政，不安其上，欲其至也。", literal: "A true king has punitive campaigns but no warfare; if a city holds out he does not assault it; if troops resist in formation he does not strike; if enemy above and below alike rejoice, he congratulates them; he does not slaughter cities, does not conceal troops, does not detain masses, and the army does not overstay its season—hence those in disorder delight in his government, are discontent with their superiors, and long for his arrival.", idiomatic: "A true king punishes but does not wage war; he does not storm cities that hold firm, strike troops that stand in formation, or fail to rejoice when foe and subject alike welcome him; he does not massacre cities, hide troops, or detain the people; his army does not outstay its season—so the disorderly delight in his rule, resent their rulers, and long for his coming." },
  { zh: "」臨武君曰：「善。", literal: "” Lord Linwu said: “Good.", idiomatic: "” Lord Linwu said: “Excellent." },
  { zh: "陳囂問荀卿曰：「先生議兵，常以仁義為本。", literal: "Chen Xi questioned Master Xun, saying: “When you, sir, discuss warfare, you always take benevolence and righteousness as the root.", idiomatic: "Chen Xi asked Master Xun: “Sir, when you discuss warfare you always take benevolence and righteousness as the foundation." },
  { zh: "仁者愛人，義者循理，然則又何以兵為？", literal: "The benevolent love others; the righteous follow principle—yet why then have armies at all?", idiomatic: "The benevolent love others; the righteous follow principle—then why have armies at all?" },
  { zh: "凡所為有兵者，為爭奪也。", literal: "All purposes for which armies exist are for contention and seizure.", idiomatic: "All purposes for which armies exist are contention and seizure." },
  { zh: "」荀卿曰：「非汝所知也。", literal: "” Master Xun said: “This is not what you understand.", idiomatic: "” Master Xun said: “That is not what you understand." },
  { zh: "彼仁者愛人，愛人，故惡人之害之也；", literal: "Those benevolent love others; loving others, they therefore hate that others harm them;", idiomatic: "The benevolent love others; loving others, they hate that others harm them;" },
  { zh: "義者循理，循理，故惡人之亂之也。", literal: "the righteous follow principle; following principle, they therefore hate that others disorder it.", idiomatic: "the righteous follow principle; following principle, they hate that others disorder it." },
  { zh: "彼兵者，所以禁暴除害也，非爭奪也。", literal: "Armies exist to restrain violence and remove harm—not for contention and seizure.", idiomatic: "Armies exist to restrain violence and remove harm—not for contention and seizure." },
  { zh: "3燕孝王薨，子喜立。", literal: "3. King Xiao of Yan died; his son Xi was enthroned.", idiomatic: "3. King Xiao of Yan died; his son Xi ascended the throne." },
  { zh: "4周民東亡。", literal: "4. The people of Zhou fled east.", idiomatic: "4. The people of Zhou fled eastward." },
  { zh: "秦人取其寶器，遷西周公於憚狐之聚。", literal: "The people of Qin took their precious vessels and moved the lord of Western Zhou to the settlement of Danhu.", idiomatic: "Qin seized their precious vessels and moved the lord of Western Zhou to the settlement of Danhu." },
  { zh: "1摎伐魏，取吳城。", literal: "1. [Qin] attacked Wei and took Wucheng.", idiomatic: "1. Qin attacked Wei and took Wucheng." },
  { zh: "韓王入朝。", literal: "The king of Han came to court.", idiomatic: "The king of Han came to court." },
  { zh: "魏舉國聽令。", literal: "Wei as a whole obeyed orders.", idiomatic: "Wei as a whole submitted to Qin’s command." },
  { zh: "1王郊見上帝於雍。", literal: "1. The king performed the suburban sacrifice and appeared before the Supreme God at Yong.", idiomatic: "1. The king performed the suburban sacrifice to the Supreme God at Yong." },
  { zh: "2楚遷于鉅陽。", literal: "2. Chu moved its capital to Juyang.", idiomatic: "2. Chu moved its capital to Juyang." },
  { zh: "1衛懷君朝於魏，魏人執而殺之；", literal: "1. Lord Huai of Wei went to court in Wei; the men of Wei seized and killed him;", idiomatic: "1. Lord Huai of Wei went to court in Wei; the Wei authorities seized and killed him;" },
  { zh: "更立其弟，是為元君。", literal: "they enthroned his younger brother, who is known as Lord Yuan.", idiomatic: "they enthroned his younger brother, known as Lord Yuan." },
  { zh: "元君，魏婿也。", literal: "Lord Yuan was a son-in-law of Wei.", idiomatic: "Lord Yuan was Wei’s son-in-law." },
  { zh: "1秋，〔後九月〕<ref>〔後九月〕據《睡虎地秦墓竹簡·編年紀》補。", literal: "1. In autumn, [the intercalary ninth month]<ref>[the intercalary ninth month]—supplemented per the “Chronological Annals” in the Shuihudi Qin tomb bamboo slips.", idiomatic: "1. In autumn, [the intercalary ninth month]<ref>[the intercalary ninth month]—supplemented per the “Chronological Annals” in the Shuihudi Qin tomb bamboo slips." },
  { zh: "</ref>，王薨，〔子〕孝文王〔柱〕立<ref>〔子〕孝文王〔柱〕立據《史記·秦本紀》索隱補。", literal: "</ref>, the king died, and [his son] King Xiaowen [Zhu] was enthroned<ref>[his son] King Xiaowen [Zhu] was enthroned—supplemented per the “Basic Annals of Qin” in the Records of the Grand Historian, Suoyin commentary.", idiomatic: "</ref>, the king died, and [his son] King Xiaowen [Zhu] ascended the throne<ref>[his son] King Xiaowen [Zhu] ascended the throne—supplemented per the “Basic Annals of Qin” in the Records, Suoyin commentary." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "尊唐八子為唐太后，以子楚為太子。", literal: "He honored the eighth son of Tang as Queen Dowager Tang and made Zichu crown prince.", idiomatic: "He honored the eighth son of the Tang clan as Queen Dowager Tang and made Zichu crown prince." },
  { zh: "趙人奉子楚妻子歸之。", literal: "The people of Zhao sent Zichu’s wife and son back to him.", idiomatic: "The people of Zhao sent Zichu’s wife and son back to Qin." },
  { zh: "韓王衰絰入吊祠。", literal: "The king of Han came in mourning garb to offer condolences and sacrifice.", idiomatic: "The king of Han came in mourning dress to offer condolences and sacrifice." },
  { zh: "2燕王喜使栗腹約歡於趙，以五百金為趙王酒。", literal: "2. King Xi of Yan sent Li Fu to cement goodwill with Zhao, presenting five hundred in gold as wine for the king of Zhao.", idiomatic: "2. King Xi of Yan sent Li Fu to cement goodwill with Zhao, presenting five hundred in gold as wine for the king of Zhao." },
  { zh: "返而言於燕王曰：「趙壯者皆死長平，其孤未壯，可伐也。", literal: "On his return he said to the king of Yan: “Zhao’s strong men all died at Changping; their orphans are not yet grown—Zhao can be attacked.", idiomatic: "On his return he told the king of Yan: “Zhao’s fighting men all died at Changping; their orphans are not yet grown—Zhao can be attacked." },
  { zh: "」王召昌國君樂閒問之，對曰：「趙四戰之國，其民習兵，不可。", literal: "” The king summoned Lord Yue Xian of Changguo and questioned him; he replied: “Zhao is a state of four-front warfare; its people are practiced in arms—it cannot be done.", idiomatic: "” The king summoned Lord Yue Xian of Changguo and asked him; he replied: “Zhao is a state fought on four fronts; its people are seasoned in arms—it cannot be done." },
  { zh: "」王曰：「吾以五而伐一。", literal: "” The king said: “With five I attack one.", idiomatic: "” The king said: “With five states I attack one.”" },
  { zh: "」對曰：「不可。", literal: "” He replied: “It cannot be done.", idiomatic: "” He replied: “It cannot be done.”" },
  { zh: "」王怒。", literal: "” The king was angry.", idiomatic: "” The king was angry." },
  { zh: "群臣皆以為可，乃發二千乘，栗腹將而攻鄗，卿秦攻代。", literal: "All the ministers thought it feasible; they thereupon raised two thousand chariots, with Li Fu as commander to attack Hao and Qing Qin to attack Dai.", idiomatic: "All the ministers thought it feasible; they raised two thousand chariots, Li Fu commanding the attack on Hao and Qing Qin the attack on Dai." },
  { zh: "將渠曰：「與人通關約交，以五百金飲人之王，使者報而攻之，不祥，師必無功。", literal: "Jiang Qu said: “Having opened the passes and made covenant friendship, giving five hundred in gold for the king of Zhao’s feast, then attacking when the envoy returns—this is inauspicious; the army will surely achieve nothing.", idiomatic: "Jiang Qu said: “You opened the passes and made a covenant, gave five hundred gold for the king of Zhao’s feast, and now attack when the envoy returns—this is ill-omened; the army will surely fail.”" },
  { zh: "」王不聽，自將偏軍隨之。", literal: "” The king would not listen and personally led a detached army following after.", idiomatic: "” The king would not listen and personally led a detached force in their wake." },
  { zh: "將渠引王之綬，王以足蹙之。", literal: "Jiang Qu pulled the king’s sash; the king kicked him away with his foot.", idiomatic: "Jiang Qu seized the king’s sash; the king kicked him away." },
  { zh: "將渠泣曰：「臣非自為，為王也！", literal: "Jiang Qu wept and said: “Your servant does not act for himself but for the king!", idiomatic: "Jiang Qu wept and said: “I do not act for myself but for Your Majesty!”" },
  { zh: "」燕師至宋子，趙廉頗為將，逆擊之，敗栗腹於鄗，〔樂乘〕敗卿秦(", literal: "” The Yan army reached Songzi; Lian Po of Zhao was general, met and struck them, defeated Li Fu at Hao, and〔Yue Cheng〕defeated Qing Qin(", idiomatic: "” The Yan army reached Songzi; Lian Po of Zhao was general, met them in battle, defeated Li Fu at Hao, and〔Yue Cheng〕defeated Qing Qin(" },
  { zh: "樂乘)", literal: "Yue Cheng)", idiomatic: "Yue Cheng)" },
  { zh: "於代，追北五百餘里<ref>〔樂乘〕敗卿秦(", literal: "at Dai, and pursued the fleeing enemy over five hundred li<ref>〔Yue Cheng〕defeated Qing Qin(", idiomatic: "at Dai and pursued the routed enemy over five hundred li<ref>〔Yue Cheng〕defeated Qing Qin(" },
  { zh: "樂乘)", literal: "Yue Cheng)", idiomatic: "Yue Cheng)" },
  { zh: "於代追北五百餘里從梁玉繩《史記志疑》移正。", literal: "at Dai pursued the fleeing enemy over five hundred li—relocated and corrected according to Liang Yusheng’s Shiji zhiyi.", idiomatic: "at Dai pursued the routed enemy over five hundred li—relocated and corrected per Liang Yusheng’s Shiji zhiyi." },
  { zh: "按樂乘為趙將，非燕將。", literal: "Note: Yue Cheng was a general of Zhao, not of Yan.", idiomatic: "Note: Yue Cheng was a Zhao general, not a Yan general." },
  { zh: "</ref>，遂圍燕。", literal: "</ref>, and then besieged Yan.", idiomatic: "</ref>, and then besieged Yan." },
  { zh: "燕人請和，趙人曰：「必令將渠處和。", literal: "The people of Yan sought peace; the people of Zhao said: “Jiang Qu must conduct the peace.", idiomatic: "The Yan sought peace; Zhao said: “Jiang Qu must conduct the peace negotiations.”" },
  { zh: "」燕王〔以〕(", literal: "” The king of Yan〔yi〕(", idiomatic: "” The king of Yan〔yi〕(" },
  { zh: "使)", literal: "shi)", idiomatic: "shi)" },
  { zh: "將渠為相而處和<ref>燕王〔以〕(", literal: "made Jiang Qu chancellor to conduct the peace<ref>The king of Yan〔yi〕(", idiomatic: "made Jiang Qu chancellor to conduct the peace<ref>The king of Yan〔yi〕(" },
  { zh: "使)", literal: "shi)", idiomatic: "shi)" },
  { zh: "將渠為相而處和章校「十二行本『使』作『以』；", literal: "made Jiang Qu chancellor to conduct the peace—Zhang’s collation: in the twelve-line edition “shi” reads “yi”;", idiomatic: "made Jiang Qu chancellor to conduct the peace—Zhang’s collation: in the twelve-line edition “shi” reads “yi”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong’s edition agrees.", idiomatic: "Kong’s edition agrees." },
  { zh: "」，《史記·趙世家》作「燕相將渠以處和」，「以」不作「使」，據改。", literal: "” The “Hereditary House of Zhao” in the Shiji reads “the Yan chancellor Jiang Qu conducted the peace with yi,” not shi—emended accordingly.", idiomatic: "” The Shiji “Hereditary House of Zhao” reads “the Yan chancellor Jiang Qu conducted the peace with yi,” not shi—emended accordingly." },
  { zh: "</ref>，趙師乃解去。", literal: "</ref>, and Zhao’s army then withdrew.", idiomatic: "</ref>, and Zhao’s army then withdrew." },
  { zh: "3趙平原君卒。", literal: "3. Lord Pingyang of Zhao died.", idiomatic: "3. Lord Pingyuan of Zhao died." },
  { zh: "1冬，十月，已亥，王即位；", literal: "1. In winter, the tenth month, on the day jihai, the king acceded;", idiomatic: "1. In winter, the tenth month, on the day jihai, the king acceded;" },
  { zh: "三日〔辛丑〕薨<ref>三日〔辛丑〕薨據《史記·秦本紀》補。", literal: "three days later〔on xinchou〕he died<ref>Three days later〔on xinchou〕he died—supplemented according to the “Basic Annals of Qin” in the Shiji.", idiomatic: "three days later〔on xinchou〕he died<ref>Three days later〔on xinchou〕he died—supplemented per the Shiji “Basic Annals of Qin.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "子楚立，是為莊襄王。", literal: "Zichu was enthroned; this is King Zhuangxiang.", idiomatic: "Zichu was enthroned as King Zhuangxiang." },
  { zh: "尊華陽夫人為華陽太后，夏姬為夏太后。", literal: "Lady Huayang was honored as Queen Dowager Huayang, and Lady Xia as Queen Dowager Xia.", idiomatic: "Lady Huayang was honored as Queen Dowager Huayang and Lady Xia as Queen Dowager Xia." },
  { zh: "2燕將攻齊聊城，拔之。", literal: "2. A Yan general attacked Liaocheng of Qi and took it.", idiomatic: "2. A Yan general attacked Qi’s Liaocheng and took it." },
  { zh: "或譖之燕王，燕將保聊城，不敢歸。", literal: "Someone slandered him to the king of Yan; the Yan general held Liaocheng and dared not return.", idiomatic: "Someone slandered him to the king of Yan; the general held Liaocheng and dared not return." },
  { zh: "齊田單攻之，歲餘不下，魯仲連乃為書，約之矢以射城中，遺燕將，為陳利害曰：「為公計者，不歸燕則歸齊。", literal: "Tian Dan of Qi attacked it; for more than a year he could not take it. Lu Zhonglian thereupon wrote a letter, tied it to an arrow and shot it into the city, and sent it to the Yan general, setting forth advantage and harm, saying: “For your lordship’s planning, if you do not return to Yan then return to Qi.", idiomatic: "Tian Dan of Qi besieged it for over a year without success. Lu Zhonglian wrote a letter, tied it to an arrow and shot it into the city for the Yan general, explaining the stakes: “For your own sake, if you will not return to Yan, then go over to Qi.”" },
  { zh: "今獨守孤城，齊兵日益而燕救不至，將何為乎？", literal: "Now you alone hold an isolated city; Qi’s troops grow daily while Yan’s relief does not arrive—what will you do?", idiomatic: "You hold a lone city; Qi’s forces grow daily while Yan sends no relief—what will you do?”" },
  { zh: "」燕將見書，泣三日，猶豫不能自決，欲歸燕，已有隙；", literal: "” When the Yan general saw the letter, he wept for three days, hesitating and unable to decide for himself; he wished to return to Yan, but there was already a rift;", idiomatic: "” The Yan general read the letter and wept for three days, unable to decide; he wished to return to Yan, but a breach already lay between them;" },
  { zh: "欲降齊，所殺虜於齊甚眾，恐已降而後見辱。", literal: "he wished to surrender to Qi, but those he had killed and captured in Qi were very many, and he feared that after surrendering he would be shamed.", idiomatic: "he wished to surrender to Qi, but he had killed and captured many in Qi and feared shame after yielding." },
  { zh: "喟然嘆曰：「與人刃我，寧我自刃！", literal: "He sighed deeply and said: “Let another blade me? Better I blade myself!", idiomatic: "He sighed and said: “Let another run me through? Better I do it myself!”" },
  { zh: "」遂自殺。", literal: "” He thereupon killed himself.", idiomatic: "” He then killed himself." },
  { zh: "聊城亂，田單克聊城。", literal: "Liaocheng fell into disorder, and Tian Dan took Liaocheng.", idiomatic: "Liaocheng fell into disorder and Tian Dan took it." },
  { zh: "歸，言魯仲連於齊，欲爵之。", literal: "On returning, he spoke of Lu Zhonglian to Qi and wished to ennoble him.", idiomatic: "On returning he reported Lu Zhonglian to Qi and wished to ennoble him." },
  { zh: "仲連逃之海上，曰：「吾富貴而詘於人，寧貧賤而輕世肆志焉！", literal: "Zhonglian fled to the sea and said: “To be rich and honored yet abased before others—better to be poor and lowly and lightly abandon the world to give free rein to one’s aims!", idiomatic: "Zhonglian fled to the sea, saying: “To be rich and honored yet bow before others—I would rather be poor and lowly, lightly quit the world, and follow my own bent!”" },
  { zh: "3魏安釐王問天下之高士於子順，子順曰：「世無其人也；", literal: "3. King Anxi of Wei asked Zishun about the highest gentlemen under Heaven; Zishun said: “There is none in the age;", idiomatic: "3. King Anxi of Wei asked Zishun who were the highest gentlemen under Heaven; Zishun said: “There is none in our age;" },
  { zh: "抑可以為次，其魯仲連乎！", literal: "yet one may take as next in rank—would it not be Lu Zhonglian!", idiomatic: "yet as next in rank—would it not be Lu Zhonglian?”" },
  { zh: "」王曰：「魯仲連強作之者，非體自然也。", literal: "” The king said: “Lu Zhonglian forces himself to it; it is not his inborn nature.", idiomatic: "” The king said: “Lu Zhonglian forces himself; that is not his inborn nature.”" },
  { zh: "」子順曰：「人皆作之。", literal: "” Zishun said: “All men force themselves.", idiomatic: "” Zishun said: “All men force themselves." },
  { zh: "作之不止，乃成君子；", literal: "Force themselves without ceasing, and one becomes a gentleman;", idiomatic: "Force themselves without ceasing, and one becomes a gentleman;" },
  { zh: "作之不變，習與體成；", literal: "force themselves without change, and habit and nature become one;", idiomatic: "force themselves without change, and habit and nature become one;" },
  { zh: "〔習與體成〕<ref>習與體成〔習與體成〕章校「十二行本『成』下有『習與體成』四字；", literal: "〔habit and nature become one〕<ref>Habit and nature become one〔habit and nature become one〕—Zhang’s collation: in the twelve-line edition after “become one” there are the four characters “habit and nature become one”;", idiomatic: "〔habit and nature become one〕<ref>Habit and nature become one〔habit and nature become one〕—Zhang’s collation: in the twelve-line edition after “become one” stand the four characters “habit and nature become one”;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同。", literal: "Kong’s edition agrees.", idiomatic: "Kong’s edition agrees." },
  { zh: "」，《孔叢子·執節》正有此四字，據補。", literal: "” The “Maintaining Integrity” in the Kongcongzi has exactly these four characters—supplemented accordingly.", idiomatic: "” The Kongcongzi “Maintaining Integrity” has exactly these four characters—supplemented accordingly." },
  { zh: "</ref>，則自然也。", literal: "</ref>, and then it is inborn nature.", idiomatic: "</ref>, and then it is inborn nature.”" },
  { zh: "1呂不韋為相國。", literal: "1. Lü Buwei became chancellor of state.", idiomatic: "1. Lü Buwei became chancellor of state." },
  { zh: "2東周君為諸侯謀伐秦，王使相國帥師討滅之，遷東周君於陽人聚。", literal: "2. The Lord of Eastern Zhou plotted with the feudal lords to attack Qin; the king sent the chancellor to lead an army to attack and destroy him, and moved the Lord of Eastern Zhou to Yangren Ju.", idiomatic: "2. The Lord of Eastern Zhou plotted with the feudal lords against Qin; the king sent the chancellor to lead an army, destroyed him, and moved the Lord of Eastern Zhou to Yangren Ju." },
  { zh: "周既不祀。", literal: "Zhou thereupon ceased its sacrifices.", idiomatic: "Zhou thereupon ceased its sacrifices." },
  { zh: "周比亡，凡有七邑：河南、洛陽、穀城、平陰、偃師、鞏、緱氏。", literal: "Zhou was on the verge of perishing; in all it had seven towns: Henan, Luoyang, Gucheng, Pingyin, Yanshi, Gong, and Gou.", idiomatic: "Zhou was near extinction; it still held seven towns: Henan, Luoyang, Gucheng, Pingyin, Yanshi, Gong, and Gou." },
  { zh: "3以河南、洛陽十萬戶封相國不韋為文信侯。", literal: "3. With the hundred thousand households of Henan and Luoyang, the chancellor Buwei was enfeoffed as Lord Wenxin.", idiomatic: "3. With the hundred thousand households of Henan and Luoyang, Chancellor Buwei was enfeoffed as Lord Wenxin." },
  { zh: "4蒙驁伐韓，取成皋、滎陽，初置三川郡。", literal: "4. Meng Ao attacked Han, took Chenggao and Xingyang, and for the first time established the commandery of Sanchuan.", idiomatic: "4. Meng Ao attacked Han, took Chenggao and Xingyang, and first established the commandery of Sanchuan." },
  { zh: "5楚滅魯，遷魯頃公於卞，為家人。", literal: "5. Chu destroyed Lu, moved Duke Qing of Lu to Bian, and made him a commoner of a household.", idiomatic: "5. Chu destroyed Lu, moved Duke Qing to Bian, and reduced him to a commoner." },
  { zh: "1〔夏，四月〕，日有食之<ref>〔夏四月〕日有食之據《史記·秦本紀》補。", literal: "1.〔Summer, fourth month〕, there was an eclipse of the sun<ref>〔Summer, fourth month〕there was an eclipse of the sun—supplemented according to the “Basic Annals of Qin” in the Shiji.", idiomatic: "1.〔Summer, fourth month〕, there was a solar eclipse<ref>〔Summer, fourth month〕solar eclipse—supplemented per the Shiji “Basic Annals of Qin.”" },
  { zh: "案：查《中國歷史日食典》，此年日食在西曆4月24日，合中國秦曆為四月初一戊子日。", literal: "Note: consulting the Zhongguo lishi rishi dian, the eclipse of this year fell on 24 April in the Western calendar, corresponding in the Qin calendar of China to the first day of the fourth month, the day wuzi.", idiomatic: "Note: per the Zhongguo lishi rishi dian, this eclipse fell on 24 April in the Western calendar, matching the first day of the fourth month in the Qin calendar, the day wuzi." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2蒙驁伐趙，〔定太原〕<ref>〔定太原〕據章校及《史記·秦本紀》補。", literal: "2. Meng Ao attacked Zhao,〔pacified Taiyuan〕<ref>〔Pacified Taiyuan〕—supplemented according to Zhang’s collation and the “Basic Annals of Qin” in the Shiji.", idiomatic: "2. Meng Ao attacked Zhao,〔pacified Taiyuan〕<ref>〔Pacified Taiyuan〕—supplemented per Zhang’s collation and the Shiji “Basic Annals of Qin.”" },
  { zh: "</ref>，取榆次、狼孟等三十七城。", literal: "</ref>, and took Yuci, Langmeng, and thirty-seven other cities.", idiomatic: "</ref>, and took Yuci, Langmeng, and thirty-seven other cities." },
  { zh: "3楚春申君言於楚王曰：「淮北地邊於齊，其事急，請以為郡而封於江東。", literal: "3. Lord Chunshen of Chu spoke to the king of Chu, saying: “The lands north of the Huai border on Qi; the matter is urgent—please make them a commandery and enfeoff me in the lands east of the Yangzi.", idiomatic: "3. Lord Chunshen said to the king of Chu: “The lands north of the Huai border Qi and the situation is urgent—make them a commandery and enfeoff me east of the Yangzi.”" },
  { zh: "」楚王許之。", literal: "” The king of Chu assented.", idiomatic: "” The king of Chu agreed." },
  { zh: "春申君因城吳故墟以為都邑，宮室極盛。", literal: "Lord Chunshen thereupon walled the old ruins of Wu to make his capital, and his palaces were extremely grand.", idiomatic: "Lord Chunshen walled the old ruins of Wu for his capital, and his palaces were magnificently lavish." },
  { zh: "1王齕攻上黨諸城，悉拔之，初置太原郡。", literal: "1. Wang He attacked the cities of Shangdang, took them all, and for the first time established the commandery of Taiyuan.", idiomatic: "1. Wang He attacked the cities of Shangdang, took them all, and first established the commandery of Taiyuan." },
  { zh: "2蒙驁帥師伐魏，取高都、汲。", literal: "2. Meng Ao led an army to attack Wei and took Gaodu and Ji.", idiomatic: "2. Meng Ao led an army against Wei and took Gaodu and Ji." },
  { zh: "魏師數敗，魏王患之，乃使人請信陵君於趙。", literal: "Wei’s army was repeatedly defeated; the king of Wei was troubled by this and sent someone to summon Lord Xinling from Zhao.", idiomatic: "Wei’s army was repeatedly beaten; the king of Wei was alarmed and sent to summon Lord Xinling from Zhao." },
  { zh: "信陵君畏得罪，不肯還，誡門下曰：「有敢為魏使通者死！", literal: "Lord Xinling feared punishment and would not return; he warned his retainers, saying: “Whoever dares admit an envoy from Wei—death!", idiomatic: "Lord Xinling feared punishment and refused to return; he warned his retainers: “Anyone who admits an envoy from Wei dies!”" },
  { zh: "」賓客莫敢諫。", literal: "” None of his guests dared remonstrate.", idiomatic: "” None of his guests dared remonstrate." },
  { zh: "毛公、薛公見信陵君曰：「公子所以重於諸侯者，徒以有魏也。", literal: "Lord Mao and Lord Xue saw Lord Xinling and said: “The reason the prince is esteemed among the feudal lords is solely that he has Wei.", idiomatic: "Lord Mao and Lord Xue called on Lord Xinling and said: “The reason you are esteemed among the feudal lords is solely that you have Wei.”" },
  { zh: "今魏急而公子不恤，一旦秦人克大梁，夷先王之宗廟，公子當何面目立天下乎！", literal: "Now Wei is in peril yet the prince does not care; if one morning the men of Qin take Daliang and level the ancestral temples of the former kings, with what face will the prince stand in the realm!", idiomatic: "Now Wei is in peril and you do not care; if Qin takes Daliang and levels your ancestral temples, with what face will you stand among the states?”" },
  { zh: "」語未卒，信陵君色變，趣駕還魏。", literal: "” Before the words were finished, Lord Xinling’s countenance changed; he hastened his carriage and returned to Wei.", idiomatic: "” Before they finished speaking, Lord Xinling’s face changed; he hastened his carriage back to Wei." },
  { zh: "魏王持信陵君而泣，以為上將軍。", literal: "The king of Wei embraced Lord Xinling and wept, and made him supreme commander.", idiomatic: "The king of Wei embraced Lord Xinling in tears and made him supreme commander." },
  { zh: "信陵君使人求援於諸侯。", literal: "Lord Xinling sent men to seek aid from the feudal lords.", idiomatic: "Lord Xinling sent men to seek aid from the feudal lords." },
  { zh: "諸侯聞信陵君復為魏將，皆遣兵救魏。", literal: "When the feudal lords heard that Lord Xinling was again general of Wei, they all sent troops to rescue Wei.", idiomatic: "When the lords heard Lord Xinling was again Wei’s general, they all sent troops to rescue Wei." },
  { zh: "信陵君率五國之師敗蒙驁於河外，蒙驁遁走。", literal: "Lord Xinling led the armies of five states and defeated Meng Ao beyond the Yellow River; Meng Ao fled.", idiomatic: "Lord Xinling led the armies of five states and defeated Meng Ao beyond the River; Meng Ao fled." },
  { zh: "信陵君追至函谷關，抑之而還。", literal: "Lord Xinling pursued to Hangu Pass, held them back, and returned.", idiomatic: "Lord Xinling pursued to Hangu Pass, held the enemy back, and withdrew." },
  { zh: "安陵人縮高之子仕於秦，秦使之守管。", literal: "The son of Suo Gao of Anling held office in Qin; Qin made him defend Guan.", idiomatic: "The son of Suo Gao of Anling served Qin; Qin appointed him to defend Guan." },
  { zh: "信陵君攻之不下，使人謂安陵君曰：「君其遣縮高，吾將仕之以五大夫，使為執節尉。", literal: "Lord Xinling attacked but could not take it; he sent someone to tell the lord of Anling: “My lord, send Suo Gao; I will employ him as a grandee of the fifth rank and make him commandant holding the staff of authority.", idiomatic: "Lord Xinling besieged it without success and sent word to the lord of Anling: “Send Suo Gao; I will employ him as a fifth-rank grandee and make him commandant holding the staff of authority.”" },
  { zh: "」安陵君曰：「安陵，小國也，不能必使其民。", literal: "” The lord of Anling said: “Anling is a small state; I cannot be sure of making my people obey.", idiomatic: "” The lord of Anling said: “Anling is a small state; I cannot compel my people to obey." },
  { zh: "使者自往請之。", literal: "The envoy may go himself to summon him.", idiomatic: "Your envoy may go summon him himself.”" },
  { zh: "」使吏導使者至縮高之所。", literal: "” He sent an officer to guide the envoy to Suo Gao’s dwelling.", idiomatic: "” He sent an officer to guide the envoy to Suo Gao’s dwelling." },
  { zh: "使者致信陵君之命，縮高曰：「君之幸高也，將使高攻管也。", literal: "The envoy delivered Lord Xinling’s command; Suo Gao said: “My lord’s favor to Gao is that he would have Gao attack Guan.", idiomatic: "The envoy delivered Lord Xinling’s command; Suo Gao said: “My lord favors me by wishing me to attack Guan." },
  { zh: "夫父攻子守，人之笑也；", literal: "For a father to attack while his son defends—men will laugh;", idiomatic: "A father attacking while his son defends—men will laugh;" },
  { zh: "見臣而下，是倍主也。", literal: "to be seen as a minister and then descend—that is betraying one’s lord.", idiomatic: "to be seen as a minister and then yield—that is betraying one’s lord." },
  { zh: "父教子倍，亦非君之所喜。", literal: "For a father to teach his son betrayal is also not what my lord would approve.", idiomatic: "For a father to teach his son betrayal is also not what you would approve.”" },
  { zh: "敢再拜辭！", literal: "I venture a second bow and decline!", idiomatic: "I respectfully decline!”" },
  { zh: "」使者以報信陵君。", literal: "” The envoy reported this to Lord Xinling.", idiomatic: "” The envoy reported this to Lord Xinling." },
  { zh: "信陵君大怒，遣使之安陵君所曰：「安陵之地，亦猶魏也。", literal: "Lord Xinling was greatly angered and sent someone to the lord of Anling’s place, saying: “The territory of Anling is also like that of Wei.", idiomatic: "Lord Xinling was furious and sent word to the lord of Anling: “Anling’s territory is part of Wei." },
  { zh: "今吾攻管而不下，則秦兵及我，社稷必危矣。", literal: "Now if I attack Guan and cannot take it, Qin’s troops will reach me and the altars of state will surely be in peril.", idiomatic: "If I cannot take Guan, Qin’s troops will reach me and the altars of state will be in peril." },
  { zh: "願君生束縮高而致之！", literal: "I wish my lord to bind Suo Gao alive and deliver him!", idiomatic: "I ask that you bind Suo Gao alive and deliver him!”" },
  { zh: "若君弗致，無忌將發十萬之師以造安陵之城下！", literal: "If my lord does not deliver him, Wuji will raise an army of a hundred thousand and march to beneath the walls of Anling!", idiomatic: "If you do not deliver him, Wuji will raise a hundred thousand men and march on Anling!”" },
  { zh: "」安陵君曰：「吾先君成侯受詔襄王以守此城也，手授太府之憲，憲之上篇曰：『子弒父，臣弒君，有常不赦。", literal: "” The lord of Anling said: “Our former lord Cheng Hou received King Xiang’s charge to hold this city; he was handed in person the statutes of the Grand Treasury, whose upper section reads: ‘A son who murders his father, a minister who murders his lord—fixed law, no pardon.", idiomatic: "” The lord of Anling said: “Our former lord Cheng Hou received King Xiang’s charge to hold this city and was handed in person the statutes of the Grand Treasury, whose upper section reads: ‘A son who murders his father, a minister who murders his lord—fixed law, no pardon." },
  { zh: "國雖大赦，降城亡子不得與焉。", literal: "Though the state grant a great amnesty, those who surrender cities or absconding sons are not included.", idiomatic: "Though the state grant a great amnesty, those who surrender cities or absconding sons are not included." },
  { zh: "』今縮高辭大位以全父子之義，而君曰『必生致之』，是使我負襄王之詔而廢太府之憲也，雖死，終不敢行！", literal: "’ Now Suo Gao declines a great post to preserve the righteousness between father and son, yet my lord says ‘You must deliver him alive’—this would make me betray King Xiang’s charge and nullify the statutes of the Grand Treasury; though I die, I dare not do it!", idiomatic: "’ Now Suo Gao declines a great post to preserve father-and-son righteousness, yet you say ‘Deliver him alive’—that would make me betray King Xiang’s charge and nullify the Grand Treasury’s statutes; though I die, I dare not do it!”" },
  { zh: "」縮高聞之曰：「信陵君為人，悍猛而自用，此辭必反為國禍。", literal: "” When Suo Gao heard this he said: “Lord Xinling by nature is fierce and headstrong and acts on his own; this demand will surely turn into disaster for the state.", idiomatic: "” When Suo Gao heard this he said: “Lord Xinling is by nature fierce, headstrong, and self-willed; this demand will surely become a disaster for the state." },
  { zh: "吾已全己，無違人臣之義矣，豈可使吾君有魏患乎！", literal: "I have already preserved myself wholly and have not violated the duty of a minister—how could I let my lord suffer trouble from Wei!", idiomatic: "I have already preserved my integrity and violated no duty as a minister—how could I let my lord suffer harm from Wei!" },
  { zh: "」乃之使者之舍，刎頸而死。", literal: "” He then went to the envoy's lodging and cut his throat and died.", idiomatic: "” He then went to the envoy's quarters and cut his throat and died." },
  { zh: "信陵君聞之，縞素辟舍，使使者謝安陵君曰：「無忌，小人也，困于思慮，失信於君，請再拜辭罪！", literal: "Lord Xinling heard of it, put on white mourning and vacated his quarters, and sent an envoy to apologize to the lord of Anling, saying, “Wuji is a petty man, trapped in poor thinking and faithless toward you. I beg to bow twice and decline my offense!", idiomatic: "Lord Xinling heard of it, dressed in white mourning and vacated his quarters, and sent an envoy to apologize to the lord of Anling, saying, “Wuji is a petty man, mired in poor judgment and faithless toward you. I beg to bow twice and ask your pardon!" },
  { zh: "王使人行萬金於魏以間信陵君，求得晉鄙客，令說魏王曰：「公子亡在外十年矣，今復為將，諸侯皆屬，天下徒聞信陵君而不聞魏王矣。", literal: "The king sent men to carry ten thousand in gold into Wei to sow discord against Lord Xinling. They obtained a former retainer of Jin Bi and had him persuade the king of Wei, saying, “The prince was in exile abroad for ten years; now he is general again. All the feudal lords submit to him. All under Heaven hears only of Lord Xinling and does not hear of the king of Wei.", idiomatic: "The king sent agents with ten thousand in gold into Wei to undermine Lord Xinling. They found a former retainer of Jin Bi and had him tell the king of Wei, “The prince was abroad ten years; now he is general again. All the feudal lords follow him. The world hears only of Lord Xinling, not of the king of Wei." },
  { zh: "」王又數使人賀信陵君：「得為魏王未也？", literal: "” The king also repeatedly sent men to congratulate Lord Xinling: “Have you become king of Wei yet?", idiomatic: "” The king also repeatedly sent men to congratulate Lord Xinling: “Have you become king of Wei yet?" },
  { zh: "」魏王日聞其毀，不能不信，乃使人代信陵君將兵。", literal: "” Day by day the king of Wei heard such slander and could not but believe it; he then sent someone to replace Lord Xinling as commander of the army.", idiomatic: "” Day after day the king of Wei heard such slander and could not but believe it; he sent someone to replace Lord Xinling as commander." },
  { zh: "信陵君自知再以毀廢，乃謝病不朝，日夜以酒色自娛，凡四歲而卒。", literal: "Lord Xinling knew himself likely to be dismissed again through slander; he therefore pleaded illness and did not attend court, day and night indulging in wine and women—for four years in all, then he died.", idiomatic: "Lord Xinling knew he might be dismissed again through slander; he pleaded illness, stopped attending court, and day and night drowned himself in wine and women. After four years he died." },
  { zh: "韓王往吊，其子榮之，以告子順。", literal: "The king of Han went to offer condolences. His son Rong received him and told this to Zishun.", idiomatic: "The king of Han came to offer condolences. His son Rong received him and told Zishun." },
  { zh: "子順曰：「必辭之以禮。", literal: "Zishun said, “You must decline with propriety.", idiomatic: "Zishun said, “You must decline with proper ceremony." },
  { zh: "『鄰國君吊，君為之主。", literal: "‘When a neighboring state's ruler comes to condole, the ruler presides as host.", idiomatic: "‘When a neighboring ruler comes to condole, the ruler himself should preside as host." },
  { zh: "』今君不命子，則子無所受韓君也。", literal: "’ Now if the ruler does not command his son, then the son has no standing to receive the king of Han.", idiomatic: "’ If the ruler does not commission his son, the son has no standing to receive the king of Han." },
  { zh: "」其子辭之。", literal: "” His son declined.", idiomatic: "” His son declined." },
  { zh: "3〔夏〕，五月<ref>〔夏〕五月據《通鑑》通例補。", literal: "3 〔Summer〕, fifth month<ref>〔Summer〕, fifth month supplemented per Zizhi Tongjian convention.", idiomatic: "3 〔Summer〕, fifth month<ref>〔Summer〕, fifth month supplemented per Zizhi Tongjian convention." },
  { zh: "</ref>，丙午，王薨。", literal: "</ref> On bingwu the king died.", idiomatic: "</ref> On bingwu the king died." },
  { zh: "太子政立，生十三年矣，國事皆〔委〕(", literal: "The crown prince Zheng was established; he was thirteen years old. All state affairs were 〔entrusted〕(", idiomatic: "The crown prince Zheng was enthroned; he was thirteen. All state affairs were 〔entrusted〕(" },
  { zh: "決)", literal: "decided)", idiomatic: "decided)" },
  { zh: "於文信侯<ref>國事皆〔委〕(", literal: "to the Lord of Wenxin<ref>All state affairs 〔entrusted〕(", idiomatic: "to the Lord of Wenxin<ref>All state affairs 〔entrusted〕(" },
  { zh: "決)", literal: "decided)", idiomatic: "decided)" },
  { zh: "於文信侯章校「十二行本『決』作『委』；", literal: "to the Lord of Wenxin—Zhang's collation: “In the twelve-line edition ‘decided’ reads ‘entrusted’;", idiomatic: "to the Lord of Wenxin—Zhang's collation: “In the twelve-line edition ‘decided’ reads ‘entrusted’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "張校同；", literal: "Zhang's collation agrees;", idiomatic: "Zhang's collation agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」，《史記·秦始皇本紀》同，據改。", literal: "” The “Basic Annals of Qin Shihuang” in the Shiji agrees; amended accordingly.", idiomatic: "” The Shiji “Basic Annals of Qin Shihuang” agrees; amended accordingly." },
  { zh: "</ref>，號稱仲父。", literal: "</ref> and he was styled Zhongfu (“father-by-protocol”).", idiomatic: "</ref> and he was styled Zhongfu, “father-by-protocol.”" },
  { zh: "4晉陽反。", literal: "4 Jinyang rebelled.", idiomatic: "4 Jinyang rebelled." },
  { zh: "1蒙驁擊定之。", literal: "1 Meng Ao attacked and settled it.", idiomatic: "1 Meng Ao attacked and put it down." },
  { zh: "2韓欲疲秦人，使無東伐，乃使水工鄭國為間於秦，鑿涇水自仲山為渠，并北山，東注洛。", literal: "2 Han wished to weary the men of Qin so they would not march east to attack; it therefore sent the hydraulic engineer Zheng Guo as a spy into Qin to cut the Jing River from Zhongshan into a canal, running along the northern mountains and east to pour into the Luo.", idiomatic: "2 Han wished to exhaust Qin's manpower so it would not march east. It sent the hydraulic engineer Zheng Guo as a spy into Qin to cut a canal from the Jing River at Zhongshan, running along the northern mountains east to the Luo." },
  { zh: "中作而覺，秦人欲殺之。", literal: "Midway through the work the plot was discovered; the men of Qin wished to kill him.", idiomatic: "Midway through the work the plot was exposed; Qin meant to kill him." },
  { zh: "鄭國曰：「臣為韓延數年之命，然渠成，亦秦萬世之利也。", literal: "Zheng Guo said, “Your servant has prolonged Han's allotted years of life by several years, yet when the canal is completed it will also be a benefit to Qin for ten thousand generations.", idiomatic: "Zheng Guo said, “I have bought Han a few more years of life, yet when the canal is finished it will benefit Qin for ages to come." },
  { zh: "」乃使卒為之。", literal: "” They then had soldiers complete it.", idiomatic: "” They then had soldiers finish it." },
  { zh: "注填閼之水溉舄鹵之地四萬餘頃，收皆畝一鐘，關中由是益富饒。", literal: "It channeled the waters of Tianque to irrigate more than forty thousand qing of saline-alkali land; harvests all reached one zhong per mu, and Guanzhong from this grew ever richer.", idiomatic: "It channeled the waters of Tianque to irrigate more than forty thousand qing of saline land; every field yielded a zhong per mu, and Guanzhong grew far richer." },
  { zh: "1麃公將卒攻卷，斬首三萬。", literal: "1 Lord Piao led troops to attack Juan and beheaded thirty thousand.", idiomatic: "1 Lord Piao led troops against Juan and beheaded thirty thousand." },
  { zh: "2趙以廉頗為假相國，伐魏，取繁陽。", literal: "2 Zhao made Lian Po acting chancellor of state, attacked Wei, and took Fanyang.", idiomatic: "2 Zhao made Lian Po acting chancellor, attacked Wei, and took Fanyang." },
  { zh: "趙孝成王薨，子悼襄王立，使武襄君樂乘代廉頗。", literal: "King Xiaocheng of Zhao died; his son King Daoxiang was established. He sent Lord Wuxiang Yue Cheng to replace Lian Po.", idiomatic: "King Xiaocheng of Zhao died; his son King Daoxiang succeeded. He sent Lord Wuxiang Yue Cheng to replace Lian Po." },
  { zh: "廉頗怒，攻武襄君，武襄君走，廉頗出奔魏。", literal: "Lian Po was angry, attacked Lord Wuxiang; Lord Wuxiang fled, and Lian Po went into exile in Wei.", idiomatic: "Lian Po in anger attacked Lord Wuxiang; Lord Wuxiang fled, and Lian Po fled to Wei." },
  { zh: "久之，魏不能信用。", literal: "After a long while Wei could not trust and employ him.", idiomatic: "After a long while Wei could not bring itself to trust him." },
  { zh: "趙師數困於秦，趙王思復得廉頗，廉頗亦思復用於趙。", literal: "Zhao's army was repeatedly hard pressed by Qin. The king of Zhao thought of getting Lian Po back; Lian Po also wished to be employed again in Zhao.", idiomatic: "Zhao's army was repeatedly beaten by Qin. The king of Zhao thought of recalling Lian Po; Lian Po also wished to serve Zhao again." },
  { zh: "趙王使使者視廉頗尚可用否。", literal: "The king of Zhao sent an envoy to see whether Lian Po was still fit for use.", idiomatic: "The king of Zhao sent an envoy to see whether Lian Po was still fit for service." },
  { zh: "廉頗之仇郭開多與使者金，令毀之。", literal: "Lian Po's enemy Guo Kai gave the envoy much gold and had him slander him.", idiomatic: "Lian Po's enemy Guo Kai gave the envoy much gold to slander him." },
  { zh: "廉頗見使者，一飯斗米，肉十斤，被甲上馬，以示可用。", literal: "Lian Po received the envoy: one meal—a peck of rice and ten jin of meat—then donned armor, mounted a horse, and showed himself fit for use.", idiomatic: "Lian Po received the envoy, ate a peck of rice and ten jin of meat in one sitting, donned armor, mounted a horse, and showed he was still fit." },
  { zh: "使者還報曰：「廉將軍雖老，尚善飯；", literal: "The envoy returned and reported, “General Lian, though old, still eats well;", idiomatic: "The envoy returned and reported, “General Lian, though old, still eats well;" },
  { zh: "然與臣坐，頃之三遺矢矣。", literal: "yet while sitting with your servant, in no time he thrice excused himself to relieve himself.", idiomatic: "yet while sitting with me, in no time he thrice excused himself to relieve himself." },
  { zh: "」趙王以為老，遂不召；", literal: "” The king of Zhao thought him too old and therefore did not summon him;", idiomatic: "” The king of Zhao judged him too old and did not summon him;" },
  { zh: "楚人陰使迎之。", literal: "the men of Chu secretly sent to welcome him.", idiomatic: "Chu secretly sent to welcome him." },
  { zh: "廉頗一為楚將，無功，曰：「我思用趙人。", literal: "Lian Po once served Chu as general without achievement and said, “I wish to employ men of Zhao.", idiomatic: "Lian Po served Chu once as general without success and said, “I wish to use men of Zhao." },
  { zh: "」卒死於壽春。", literal: "” In the end he died at Shouchun.", idiomatic: "” In the end he died at Shouchun." },
  { zh: "1大饑。", literal: "1 Great famine.", idiomatic: "1 Great famine." },
  { zh: "2蒙驁伐韓，取十二城。", literal: "2 Meng Ao attacked Han and took twelve cities.", idiomatic: "2 Meng Ao attacked Han and took twelve cities." },
  { zh: "3趙王以李牧為將，伐燕，取武遂、方城。", literal: "3 The king of Zhao made Li Mu general, attacked Yan, and took Wusui and Fangcheng.", idiomatic: "3 The king of Zhao made Li Mu general, attacked Yan, and took Wusui and Fangcheng." },
  { zh: "李牧者，趙之北邊良將也，嘗居代、雁門備匈奴，以便宜置吏，市租皆輸入莫府，為士卒費，日擊數牛饗士；", literal: "Li Mu was a fine general on Zhao's northern frontier. He had long dwelt at Dai and Yanmen to guard against the Xiongnu, appointing officers as circumstances allowed; market taxes all went into the commander's treasury for soldiers' expenses, and each day he slaughtered several oxen to feast the troops;", idiomatic: "Li Mu was a fine general on Zhao's northern frontier. He had long held Dai and Yanmen against the Xiongnu, appointing officers as he saw fit; market taxes all went to his headquarters for the troops, and each day he slaughtered several oxen to feast the men;" },
  { zh: "習騎射，謹烽火，多間諜，為約曰：「匈奴即入盜，急入收保。", literal: "he trained mounted archery, kept watch on beacon-fires, and employed many spies. He made a covenant, saying, “If the Xiongnu come in to plunder, hurry into the forts and strongholds.", idiomatic: "he drilled mounted archery, kept beacon-fires strict, and employed many spies. His rule was: “If the Xiongnu raid, hurry into the forts." },
  { zh: "有敢捕虜者斬！", literal: "Whoever dares capture prisoners—behead!", idiomatic: "Whoever dares take prisoners—behead!" },
  { zh: "」匈奴每入，烽火謹，輒入收保不戰。", literal: "” Whenever the Xiongnu entered, the beacons were strict; they would at once enter the forts and hold fast without fighting.", idiomatic: "” Whenever the Xiongnu came, the beacons were alert; his men at once withdrew into the forts and would not fight." },
  { zh: "如是數歲，亦不亡失。", literal: "Thus for several years they neither perished nor lost ground.", idiomatic: "Thus for several years they lost neither men nor ground." },
  { zh: "匈奴皆以為怯，雖趙邊兵亦以為吾將怯。", literal: "The Xiongnu all thought them cowardly; even Zhao's border troops thought our general was cowardly.", idiomatic: "The Xiongnu all thought them cowards; even Zhao's border troops thought their general was a coward." },
  { zh: "趙王讓之，李牧如故。", literal: "The king of Zhao reproached him, but Li Mu was as before.", idiomatic: "The king of Zhao reproached him, but Li Mu acted as before." },
  { zh: "王怒，使他人代之。", literal: "The king was angry and had another man replace him.", idiomatic: "The king in anger replaced him with another." },
  { zh: "歲餘，屢出戰，不利，多失亡，邊不得田畜。", literal: "After more than a year they repeatedly went out to fight without success; losses were many, and the border could not farm or herd.", idiomatic: "After more than a year the new commander fought repeatedly without success; losses were heavy, and the border could neither farm nor herd." },
  { zh: "王復請李牧，李牧杜門稱病不出。", literal: "The king again asked for Li Mu. Li Mu shut his door, claimed illness, and would not come out.", idiomatic: "The king again asked for Li Mu. Li Mu shut his door, pleaded illness, and would not come out." },
  { zh: "王強起之，李牧曰：「〔王〕必(", literal: "The king insisted on raising him up. Li Mu said, “〔If Your Majesty〕must(", idiomatic: "The king insisted on summoning him. Li Mu said, “〔If Your Majesty〕must(" },
  { zh: "欲)", literal: "wish to)", idiomatic: "wish to)" },
  { zh: "用臣<ref>〔王〕必(", literal: "employ your servant<ref>〔Your Majesty〕must(", idiomatic: "employ me<ref>〔Your Majesty〕must(" },
  { zh: "欲)", literal: "wish to)", idiomatic: "wish to)" },
  { zh: "用臣章校「十二行本『必欲用臣』作『王必用臣』；", literal: "employ your servant—Zhang's collation: “In the twelve-line edition ‘must wish to employ your servant’ reads ‘the king must employ your servant’;", idiomatic: "employ me—Zhang's collation: “In the twelve-line edition ‘must wish to employ your servant’ reads ‘the king must employ your servant’;" },
  { zh: "乙十一行本同；", literal: "the Yi eleven-line edition agrees;", idiomatic: "the Yi eleven-line edition agrees;" },
  { zh: "孔本同；", literal: "Kong's edition agrees;", idiomatic: "Kong's edition agrees;" },
  { zh: "退齋校同。", literal: "Tui Zhai's collation agrees.", idiomatic: "Tui Zhai's collation agrees." },
  { zh: "」《史記·廉頗列傳》同，據改。", literal: "” The “Biographies of Lian Po and Lin Xiangru” in the Shiji agrees; amended accordingly.", idiomatic: "” The Shiji “Biographies of Lian Po and Lin Xiangru” agrees; amended accordingly." },
  { zh: "</ref>，臣如前，乃敢奉令。", literal: "</ref> your servant will be as before—only then do I dare accept the command.", idiomatic: "</ref> I must act as before—only then do I dare accept command." },
  { zh: "」王許之。", literal: "” The king granted it.", idiomatic: "” The king agreed." },
  { zh: "李牧至邊，如約。", literal: "Li Mu reached the border and acted as before.", idiomatic: "Li Mu reached the border and kept his old ways." },
  { zh: "匈奴數歲無所得，終以為怯。", literal: "For several years the Xiongnu gained nothing and in the end still thought them cowardly.", idiomatic: "For several years the Xiongnu gained nothing and still thought them cowards." },
  { zh: "邊士日得賞賜而不用，皆願一戰。", literal: "The border troops daily received rewards yet had no use for them; all wished for one battle.", idiomatic: "The border troops daily received rewards yet had no chance to spend them; all yearned for a fight." },
  { zh: "於是乃具選車得千三百乘，選騎得萬三千匹，百金之士五萬人，彀者十萬人，悉勒習戰；", literal: "Thereupon he fully prepared: selected chariots, thirteen hundred; selected horsemen, thirteen thousand; warriors worth a hundred in gold, fifty thousand; archers, one hundred thousand—all were mustered and drilled for battle;", idiomatic: "Thereupon he mustered thirteen hundred chosen chariots, thirteen thousand horsemen, fifty thousand elite warriors, and one hundred thousand archers, and drilled them all for battle;" },
  { zh: "大縱畜牧、人民滿野。", literal: "he greatly loosened herding; people and livestock filled the fields.", idiomatic: "he let herds and people roam freely until the countryside was full." },
  { zh: "匈奴小入，佯北不勝，以數十人委之。", literal: "The Xiongnu made a small incursion. He feigned defeat and fled north, abandoning several tens of men to them.", idiomatic: "The Xiongnu raided in small force. He feigned defeat and fled, leaving a few dozen men as bait." },
  { zh: "單于聞之，大率眾來入。", literal: "The chanyu heard of it and came in force at the head of the host.", idiomatic: "The chanyu heard of it and led the main host in." },
  { zh: "李牧多為奇陳，張左、右翼擊之，大破之，殺匈奴十餘萬騎，滅衣詹襤，破東胡，降林胡。", literal: "Li Mu set many ambush formations, deployed left and right wings to strike them, and routed them utterly. He killed more than one hundred thousand Xiongnu horsemen, destroyed Yi-Zhanlan, broke the Eastern Hu, and received the surrender of the Forest Hu.", idiomatic: "Li Mu laid many ambushes, struck with left and right wings, and routed them. He killed more than one hundred thousand Xiongnu horsemen, destroyed the Chanru, broke the Eastern Hu, and received the Forest Hu's surrender." },
  { zh: "單于奔走，十餘歲不敢近趙邊。", literal: "The chanyu fled; for more than ten years he did not dare approach Zhao's border.", idiomatic: "The chanyu fled; for more than ten years he did not dare approach Zhao's border." },
  { zh: "先是時，天下冠帶之國七，而三國邊於戎狄：秦自隴以西有綿諸、緄戎、翟、豲之戎，岐、梁、涇、漆之北有義渠、大荔、烏氏、朐衍之戎；", literal: "Before this time there were seven civilized states under Heaven, and three states bordered the Rong and Di: west of Long, Qin had the Rong of Mianzhu, Kunrong, Di, and Quan; north of Qi, Liang, Jing, and Qi was the Rong of Yiqu, Dali, Wushi, and Quyan;", idiomatic: "Before this there were seven civilized states under Heaven, and three bordered the Rong and Di: west of Long, Qin faced the Rong of Mianzhu, Kunrong, Di, and Quan; north of Qi, Liang, Jing, and Qi lay the Rong of Yiqu, Dali, Wushi, and Quyan;" },
  { zh: "而趙北有林胡、樓煩之戎；", literal: "north of Zhao were the Rong of the Forest Hu and Loufan;", idiomatic: "north of Zhao were the Forest Hu and Loufan;" },
  { zh: "燕北有東胡、山戎；", literal: "north of Yan were the Eastern Hu and Mountain Rong;", idiomatic: "north of Yan were the Eastern Hu and Mountain Rong;" },
  { zh: "各分散居溪谷，自有君長，往往而聚者百有餘戎，然莫能相一。", literal: "each scattered, dwelling in ravines and valleys, with their own chiefs. Those gathering here and there numbered more than a hundred Rong groups, yet none could unite them.", idiomatic: "each scattered in valleys with their own chiefs; more than a hundred Rong groups gathered here and there, yet none could unite them." },
  { zh: "其後義渠築城郭以自守，而秦稍蠶食之，至惠王遂拔義渠二十五城。", literal: "Later Yiqu built walls and cities to hold itself, while Qin gradually nibbled it away; by King Hui's time it had taken twenty-five cities of Yiqu.", idiomatic: "Later Yiqu walled its towns for defense while Qin gradually consumed it; by King Hui, Qin had taken twenty-five Yiqu cities." },
  { zh: "昭王之時，宣太后誘義渠王，殺諸甘泉，遂發兵伐義渠，滅之；", literal: "In King Zhao's time the Queen Dowager Xuan lured the king of Yiqu and killed him at Ganquan; she then sent troops to attack Yiqu and destroyed it;", idiomatic: "Under King Zhao the Queen Dowager Xuan lured the king of Yiqu and killed him at Ganquan, then sent troops against Yiqu and destroyed it;" },
  { zh: "始於隴西、北地、上郡築長城以拒胡。", literal: "she then began building the Long Wall at Longxi, Beidi, and Shang commanderies to repulse the Hu.", idiomatic: "she then began building the Long Wall in Longxi, Beidi, and Shang to repulse the Hu." },
  { zh: "趙武靈王北破林胡、樓煩，築長城，自代並陰山下，至高闕為塞，而置雲中、雁門、代郡。", literal: "King Wuling of Zhao broke the Forest Hu and Loufan in the north, built the Long Wall from Dai along the foot of Yinshan to Gaogue as a barrier, and established the commanderies of Yunzhong, Yanmen, and Dai.", idiomatic: "King Wuling of Zhao defeated the Forest Hu and Loufan in the north, built the Long Wall from Dai along Yinshan to Gaogue as a barrier, and set up Yunzhong, Yanmen, and Dai commanderies." },
  { zh: "其後燕將秦開為質於胡，胡甚信之；", literal: "Later the Yan general Qin Kai was sent as hostage among the Hu; the Hu trusted him greatly;", idiomatic: "Later the Yan general Qin Kai was a hostage among the Hu, and they trusted him deeply;" },
  { zh: "歸而襲破東胡，東胡卻千餘里；", literal: "on his return he struck and broke the Eastern Hu, and the Eastern Hu retreated more than a thousand li;", idiomatic: "on returning he struck and broke the Eastern Hu, who retreated more than a thousand li;" },
  { zh: "燕亦築長城，自造陽至襄平，置上谷、漁陽、右北平、遼東郡以距胡。", literal: "Yan also built the Long Wall from Zaoyang to Xiangping, establishing the commanderies of Shanggu, Yuyang, Youbeiping, and Liaodong to keep off the Hu.", idiomatic: "Yan also built the Long Wall from Zaoyang to Xiangping and set up Shanggu, Yuyang, Youbeiping, and Liaodong to hold off the Hu." },
  { zh: "及戰國之末而匈奴始大。", literal: "By the end of the Warring States period the Xiongnu began to grow great.", idiomatic: "By the end of the Warring States the Xiongnu began to rise." },
  { zh: "1春，蒙驁伐魏，取暘、有詭。", literal: "1 In spring Meng Ao attacked Wei and took Yang and Yougui.", idiomatic: "1 In spring Meng Ao attacked Wei and took Yang and Yougui." },
  { zh: "三月，軍罷。", literal: "In the third month the army was dismissed.", idiomatic: "In the third month the army withdrew." },
  { zh: "2秦質子歸自趙；", literal: "2 Qin's hostage returned from Zhao;", idiomatic: "2 Qin's hostage returned from Zhao;" },
  { zh: "趙太子出歸國。", literal: "Zhao's crown prince went out and returned to his state.", idiomatic: "Zhao's crown prince left and returned home." },
  { zh: "3〔秋〕，七月，〔庚寅〕<ref>〔秋〕七月〔庚寅〕「秋」，據《通鑑》通例補。", literal: "3 〔Autumn〕, seventh month, 〔gengyin〕<ref>〔Autumn〕, seventh month, 〔gengyin〕—“Autumn” supplemented per Zizhi Tongjian convention.", idiomatic: "3 〔Autumn〕, seventh month, 〔gengyin〕<ref>〔Autumn〕, seventh month, 〔gengyin〕—“Autumn” supplemented per Zizhi Tongjian convention." },
  { zh: "「七月庚寅」，《史記·秦始皇本紀》作「十月庚寅」，《六國年表》作「七月」。", literal: "“Seventh month, gengyin”—the “Basic Annals of Qin Shihuang” in the Shiji reads “tenth month, gengyin”; the “Chronological Table of the Six States” reads “seventh month.”", idiomatic: "“Seventh month, gengyin”—the Shiji “Basic Annals of Qin Shihuang” reads “tenth month, gengyin”; the “Chronological Table of the Six States” reads “seventh month.”" },
  { zh: "案：此年十月無庚寅日，七月有，《始皇本紀》「十月」當為「七月」之誤，據補。", literal: "Examination: in this year the tenth month has no gengyin day; the seventh month does. “Tenth month” in the “Basic Annals of the First Emperor” should be an error for “seventh month”; supplemented accordingly.", idiomatic: "Examination: that year the tenth month has no gengyin day; the seventh month does. “Tenth month” in the “Basic Annals of the First Emperor” should be an error for “seventh month”; supplemented accordingly." },
  { zh: "</ref>，蝗，疫。", literal: "</ref> locusts; pestilence.", idiomatic: "</ref> locusts; pestilence." },
  { zh: "令百姓納粟千石，拜爵一級。", literal: "He ordered the common people: whoever submitted a thousand shi of grain would be advanced one rank of nobility.", idiomatic: "He ordered that any commoner who paid in a thousand shi of grain would advance one noble rank." },
  { zh: "4魏安釐王薨，子景湣王〔午〕立<ref>子景湣王〔午〕立據《史記·魏世家》索隱引《世本》補。", literal: "4 King Anxi of Wei died; his son King Jingmin 〔Wu〕 was established<ref>King Jingmin 〔Wu〕 established—supplemented per Suoyin to the “House of Wei” in the Shiji citing the Shiben.", idiomatic: "4 King Anxi of Wei died; his son King Jingmin 〔Wu〕 succeeded<ref>King Jingmin 〔Wu〕 established—supplemented per Suoyin to the Shiji “House of Wei” citing the Shiben." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1蒙驁伐魏，取酸棗、燕、虛、長平、雍丘、山陽等〔二〕(", literal: "1 Meng Ao attacked Wei and took Suanzao, Yan, Xu, Changping, Yongqiu, Shanyang, and the like—〔twenty〕(", idiomatic: "1 Meng Ao attacked Wei and took Suanzao, Yan, Xu, Changping, Yongqiu, Shanyang, and the like—〔twenty〕(" },
  { zh: "三)", literal: "three)", idiomatic: "three)" },
  { zh: "十城<ref>取酸棗燕虛長平雍丘山陽等〔二〕(", literal: "cities<ref>Taking Suanzao, Yan, Xu, Changping, Yongqiu, Shanyang, and the like 〔twenty〕(", idiomatic: "cities<ref>Taking Suanzao, Yan, Xu, Changping, Yongqiu, Shanyang, and the like 〔twenty〕(" },
  { zh: "三)", literal: "three)", idiomatic: "three)" },
  { zh: "十城「三十」，《史記·秦始皇本紀》、《六國年表》、《魏世家》、《魏公子列傳》、《蒙恬列傳》並作「二十」，據改。", literal: "cities reads “thirty”; the “Basic Annals of Qin Shihuang,” “Chronological Table of the Six States,” “House of Wei,” “Hereditary House of the Lord of Wei,” and “Biography of Meng Tian” all read “twenty”; amended accordingly.", idiomatic: "cities reads “thirty”; the Shiji “Basic Annals of Qin Shihuang,” “Chronological Table of the Six States,” “House of Wei,” “Hereditary House of the Lord of Wei,” and “Biography of Meng Tian” all read “twenty”; amended accordingly." },
  { zh: "</ref>；", literal: "</ref>;", idiomatic: "</ref>;" },
  { zh: "初置東郡。", literal: "The Eastern Commandery was first established.", idiomatic: "The Eastern Commandery was first established." },
  { zh: "2初，劇辛在趙與龐煖善，已而仕燕。", literal: "2 Earlier, Ju Xin had been on good terms with Pang Nuan in Zhao; later he entered the service of Yan.", idiomatic: "2 Earlier Ju Xin had been friendly with Pang Nuan in Zhao; later he entered Yan's service." },
  { zh: "燕王見趙數困於秦，廉頗去而龐煖為將，欲因其敝而攻之，問於劇辛，對曰：「龐煖易與耳。", literal: "The king of Yan saw Zhao repeatedly hard pressed by Qin, Lian Po gone and Pang Nuan made general; wishing to attack while Zhao was exhausted, he asked Ju Xin, who replied, “Pang Nuan is easy to deal with.", idiomatic: "The king of Yan saw Zhao repeatedly beaten by Qin, Lian Po gone and Pang Nuan made general; wishing to strike while Zhao was exhausted, he asked Ju Xin, who replied, “Pang Nuan is easy to handle." },
  { zh: "」燕王使劇辛將而伐趙。", literal: "” The king of Yan had Ju Xin lead an army to attack Zhao.", idiomatic: "” The king of Yan sent Ju Xin as general to attack Zhao." },
  { zh: "趙龐煖禦之，殺劇辛，取燕師二萬。", literal: "Pang Nuan of Zhao met him in defense, killed Ju Xin, and captured twenty thousand of the Yan army.", idiomatic: "Pang Nuan of Zhao met him, killed Ju Xin, and took twenty thousand Yan troops." },
  { zh: "3諸侯患秦攻伐無已時。", literal: "3 The feudal lords were troubled that Qin's attacks and campaigns had no end.", idiomatic: "3 The feudal lords were alarmed that Qin's campaigns never ceased." },
  { zh: "1楚、趙、魏、韓、〔燕〕(", literal: "1 Chu, Zhao, Wei, Han, 〔Yan〕(", idiomatic: "1 Chu, Zhao, Wei, Han, 〔Yan〕(" },
  { zh: "衛)", literal: "Wei)", idiomatic: "Wei)" },
  { zh: "合從以伐秦<ref>楚趙魏韓〔燕〕(", literal: "formed a horizontal alliance to attack Qin<ref>Chu, Zhao, Wei, Han 〔Yan〕(", idiomatic: "formed a horizontal alliance to attack Qin<ref>Chu, Zhao, Wei, Han 〔Yan〕(" },
  { zh: "衛)", literal: "Wei)", idiomatic: "Wei)" },
  { zh: "合從以伐秦從梁玉繩《史記志疑》說改。", literal: "formed a horizontal alliance to attack Qin—amended per Liang Yusheng's Shiji Zhiyi.", idiomatic: "formed a horizontal alliance to attack Qin—amended per Liang Yusheng's Shiji Zhiyi." },
  { zh: "</ref>，楚王為從長，春申君用事，取壽陵。", literal: "</ref> The king of Chu was alliance chief; Lord Chun Shen held power and took Shouling.", idiomatic: "</ref> The king of Chu was chief of the alliance; Lord Chun Shen held power and took Shouling." },
  { zh: "至函谷，秦師出，五國之師皆敗走。", literal: "When they reached Hangu Pass, Qin's army came out and the armies of the five states all were defeated and fled.", idiomatic: "At Hangu Pass Qin's army came out and the five allied armies were routed and fled." },
  { zh: "楚王以咎春申君，春申君以此益疏。", literal: "The king of Chu blamed Lord Chun Shen; Lord Chun Shen from this grew ever more estranged.", idiomatic: "The king of Chu blamed Lord Chun Shen, who from this grew ever more distant from favor." },
  { zh: "觀津人朱英謂春申君曰：「人皆以楚為強，君用之而弱。", literal: "Zhu Ying of Guanjin said to Lord Chun Shen, “All say Chu is strong, yet when you employ it, it grows weak.", idiomatic: "Zhu Ying of Guanjin said to Lord Chun Shen, “Everyone says Chu is strong, yet under your management it grows weak." },
  { zh: "其於英不然。", literal: "That is not so in Ying's case.", idiomatic: "That is not how I see it." },
  { zh: "先君時，秦善楚，二十年而不攻楚，何也？", literal: "In our late lord's time Qin was on good terms with Chu and for twenty years did not attack Chu—why?", idiomatic: "In our late lord's time Qin was friendly with Chu and for twenty years did not attack—why?" },
  { zh: "秦逾黽阨之塞而攻楚，不便；", literal: "For Qin to cross the Mengyi pass and attack Chu was inconvenient;", idiomatic: "For Qin to cross the Mengyi pass and attack Chu was impractical;" },
  { zh: "假道於兩周，背韓、魏而攻楚，不可。", literal: "to borrow a route through the two Zhou states and, with Han and Wei at its back, attack Chu—could not be done.", idiomatic: "to borrow a route through the two Zhou states and attack Chu with Han and Wei at its rear was impossible." },
  { zh: "今則不然。", literal: "Now it is not so.", idiomatic: "Now it is no longer so." },
  { zh: "魏旦暮亡，不能愛許、鄢陵，魏割以與秦，秦兵去陳百六十里。", literal: "Wei is on the verge of perishing day and night; it cannot cherish Xu and Yanling. Wei will cede territory to Qin, and Qin's army will be only one hundred sixty li from Chen.", idiomatic: "Wei is dying by the day; it cannot hold Xu and Yanling. Wei will cede land to Qin, and Qin's army will stand only one hundred sixty li from Chen." },
  { zh: "臣之所觀者，見秦、楚之日鬥也。", literal: "What your servant observes is that he sees Qin and Chu fighting day by day.", idiomatic: "What I see is Qin and Chu fighting day by day." },
  { zh: "」楚於是去陳，徙壽春，命曰郢。", literal: "” Chu thereupon left Chen, moved the capital to Shouchun, and named it Ying.", idiomatic: "” Chu thereupon abandoned Chen, moved the capital to Shouchun, and named it Ying." },
  { zh: "春申君就封於吳，行相事。", literal: "Lord Chun Shen took his fief at Wu and acted as chancellor.", idiomatic: "Lord Chun Shen took his fief at Wu and served as chancellor." },
  { zh: "2秦拔魏朝歌，及衛濮陽。", literal: "2 Qin took Zhaoge of Wei and Puyang of Wei.", idiomatic: "2 Qin took Zhaoge from Wei and Puyang from Wei." },
  { zh: "衛元君率其支屬徙居野王，阻其山以保魏之河內。", literal: "Lord Yuan of Wei led his collateral kin to move and dwell at Yewang, using the mountains as a barrier to protect Wei's Henei.", idiomatic: "Lord Yuan of Wei led his collateral kin to relocate to Yewang, using the mountains to shield Wei's Henei." },
  { zh: "1伐魏，取汲。", literal: "1 He attacked Wei and took Ji.", idiomatic: "1 Qin attacked Wei and took Ji." },
  { zh: "2夏太后薨。", literal: "2 Queen Dowager Xia died.", idiomatic: "2 Queen Dowager Xia died." },
  { zh: "3蒙驁卒。", literal: "3 Meng Ao died.", idiomatic: "3 Meng Ao died." },
  { zh: "1魏與趙鄴。", literal: "1 Wei made peace with Zhao at Ye.", idiomatic: "1 Wei made peace with Zhao at Ye." },
  { zh: "2韓桓惠王薨，子安立。", literal: "2 King Huanhui of Han died; his son An was established.", idiomatic: "2 King Huanhui of Han died; his son An succeeded." },
  { zh: "1伐魏，取垣、蒲〔陽〕<ref>蒲〔陽〕據《史記·六國年表》、《魏世家》補。", literal: "1 He attacked Wei and took Yuan and Pu 〔Yang〕<ref>Pu 〔Yang〕 supplemented per the “Chronological Table of the Six States” and “House of Wei” in the Shiji.", idiomatic: "1 Qin attacked Wei and took Yuan and Pu 〔Yang〕<ref>Pu 〔Yang〕 supplemented per the Shiji “Chronological Table of the Six States” and “House of Wei.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2夏，四月，寒，民有凍死者。", literal: "2 In summer, the fourth month, it was cold; among the people some froze to death.", idiomatic: "2 In summer, the fourth month, it was cold; some commoners froze to death." },
  { zh: "3王宿雍。", literal: "3 The king lodged at Yong.", idiomatic: "3 The king stayed at Yong." },
  { zh: "4己酉，王冠，帶劍。", literal: "4 On jiyou the king was capped and girded with a sword.", idiomatic: "4 On jiyou the king came of age, was capped, and wore a sword." },
  { zh: "5楊端和伐魏，取衍氏。", literal: "5 Yang Duanhe attacked Wei and took Yanshi.", idiomatic: "5 Yang Duanhe attacked Wei and took Yanshi." },
  { zh: "6初，王即位，年少，太后時時與文信侯私通。", literal: "6 Earlier, when the king was first established, he was young; the queen dowager from time to time had illicit relations with the Lord of Wenxin.", idiomatic: "6 Earlier, when the king first took the throne, he was young; the queen dowager from time to time had an affair with the Lord of Wenxin." },
  { zh: "王益壯，文信侯恐事覺，禍及己，乃詐以舍人嫪毐為宦者，進於太后。", literal: "As the king grew more mature, the Lord of Wenxin feared the affair would be discovered and calamity reach himself; he therefore falsely presented his retainer Lao Ai as a eunuch and introduced him to the queen dowager.", idiomatic: "As the king matured, the Lord of Wenxin feared exposure and harm to himself; he therefore falsely presented his retainer Lao Ai as a eunuch and introduced him to the queen dowager." },
  { zh: "太后幸之，生二子，封毐為長信侯，以太原為毐國，政事皆決於毐；", literal: "The queen dowager favored him and bore two sons. Lao Ai was enfeoffed as marquis of Changxin; Taiyuan was made Lao Ai's state; all government affairs were decided by Lao Ai;", idiomatic: "The queen dowager favored him and bore two sons. Lao Ai was enfeoffed as marquis of Changxin; Taiyuan was made Lao Ai's domain; all affairs were decided by Lao Ai;" },
  { zh: "客求為毐舍人者甚眾。", literal: "guests seeking to become Lao Ai's retainers were very numerous.", idiomatic: "many sought to become Lao Ai's retainers." },
  { zh: "王左右有與毐爭言者，告毐實非宦者，王下吏治毐。", literal: "Among those at the king's side, one who had quarreled in words with Lao Ai reported that Lao Ai was in truth not a eunuch. The king sent officials down to investigate Lao Ai.", idiomatic: "Someone at court who had quarreled with Lao Ai reported that he was not truly a eunuch. The king had officials investigate Lao Ai." },
  { zh: "毐懼，矯王御璽發兵，欲攻蘄年宮為亂。", literal: "Lao Ai was afraid; he forged the king's imperial seal and raised troops, intending to attack Qinian Palace and make rebellion.", idiomatic: "Lao Ai in fear forged the king's seal, raised troops, and meant to attack Qinian Palace in rebellion." },
  { zh: "王使相國、昌平君、昌文君發卒攻毐，戰咸陽，斬首數百；", literal: "The king sent the chancellor of state, Lord Changping, and Lord Changwen to raise soldiers and attack Lao Ai. They fought at Xianyang and beheaded several hundred;", idiomatic: "The king sent the chancellor, Lord Changping, and Lord Changwen with troops against Lao Ai. They fought at Xianyang and beheaded several hundred;" },
  { zh: "毐敗走，獲之。", literal: "Lao Ai was defeated and fled; he was captured.", idiomatic: "Lao Ai was defeated and fled but was captured." },
  { zh: "秋，九月，夷毐三族；", literal: "In autumn, the ninth month, Lao Ai's three clans were exterminated;", idiomatic: "In autumn, the ninth month, Lao Ai's three clans were exterminated;" },
  { zh: "黨與皆車裂滅宗；", literal: "his partisans were all torn apart by chariots and their lineages destroyed;", idiomatic: "his followers were all torn apart by chariots and their lineages destroyed;" },
  { zh: "舍人罪輕者徙蜀，凡四千餘家。", literal: "retainers whose offense was light were banished to Shu—in all more than four thousand households.", idiomatic: "lighter offenders among his retainers were banished to Shu—more than four thousand households in all." },
  { zh: "遷太后於雍萯陽宮，殺其二子。", literal: "The queen dowager was moved to Fuyang Palace at Yong, and her two sons were killed.", idiomatic: "The queen dowager was moved to Fuyang Palace at Yong, and her two sons were killed." },
  { zh: "下令曰：「敢以太后事諫者，戮而殺之，斷其四支，積之闕下！", literal: "An order was issued: “Whoever dares remonstrate on the queen dowager's affair—execute and kill him, sever his four limbs, and pile them beneath the gate tower!", idiomatic: "An edict declared: “Whoever dares remonstrate about the queen dowager—kill him, sever his four limbs, and pile them beneath the gate tower!" },
  { zh: "」死者二十七人。", literal: "” Twenty-seven died.", idiomatic: "” Twenty-seven died." },
  { zh: "齊客茅焦上謁請諫。", literal: "Mao Jiao, a guest from Qi, presented himself at audience to request to remonstrate.", idiomatic: "Mao Jiao, a guest from Qi, came to court and asked to remonstrate." },
  { zh: "王使謂之曰：「若不見夫積闕下者邪？", literal: "The king sent to tell him, “Do you not see those piled beneath the gate tower?", idiomatic: "The king sent word: “Have you not seen those piled beneath the gate tower?" },
  { zh: "」對曰：「臣聞天有二十八宿，今死者二十七人，臣之來固欲滿其數耳。", literal: "” He replied, “Your servant has heard that Heaven has twenty-eight mansions; now twenty-seven are dead. Your servant's coming was indeed to complete the number.", idiomatic: "” He replied, “I have heard Heaven has twenty-eight mansions; twenty-seven are dead. I came precisely to complete the number." },
  { zh: "臣非畏死者也！", literal: "Your servant is not one who fears death!", idiomatic: "I do not fear death!" },
  { zh: "」使者走入白之。", literal: "” The envoy ran in to report it.", idiomatic: "” The messenger ran in to report this." },
  { zh: "茅焦邑子同食者，盡負其衣物而逃王。", literal: "Mao Jiao's fellow townsmen who ate together all shouldered their clothes and fled from the king.", idiomatic: "Mao Jiao's fellow townsmen who had shared meals with him all shouldered their belongings and fled." },
  { zh: "王大怒曰：「是人也，故來犯吾，趣召鑊烹之，是安得積闕下哉！", literal: "The king was greatly angry and said, “This man has come on purpose to offend me. Hurry—summon the cauldron and boil him! How could he be piled beneath the gate tower!", idiomatic: "The king raged: “This man came deliberately to insult me. Summon the cauldron and boil him! How could he be piled beneath the gate tower!" },
  { zh: "」王按劍怒而坐，口正沫出。", literal: "” The king gripped his sword in anger and sat; foam flew from the corners of his mouth.", idiomatic: "” The king gripped his sword in fury, foam at his lips." },
  { zh: "使者召之入，茅焦徐行至前，再拜謁起，稱曰：「臣聞有生者不諱死，有國者不諱亡。", literal: "The envoy summoned him in. Mao Jiao walked slowly forward, bowed twice, rose from his audience, and said, “Your servant has heard that one who has life does not taboo death, and one who has a state does not taboo perishing.", idiomatic: "The messenger summoned him in. Mao Jiao walked slowly forward, bowed twice, rose, and said, “I have heard that the living do not shrink from death, and rulers do not shrink from ruin." },
  { zh: "諱死者不可以得生，諱亡者不可以得存。", literal: "One who taboos death cannot thereby obtain life; one who taboos perishing cannot thereby obtain preservation.", idiomatic: "Those who shrink from death cannot gain life; those who shrink from ruin cannot preserve their state." },
  { zh: "死生存亡，聖主所欲急聞也，陛下欲聞之乎？", literal: "Death, life, survival, and perishing—what a sage ruler most wishes urgently to hear—does Your Majesty wish to hear them?", idiomatic: "Death, life, survival, and ruin are what a sage ruler most urgently needs to hear—does Your Majesty wish to hear them?" },
  { zh: "」王曰：「何謂也？", literal: "” The king said, “What do you mean?", idiomatic: "” The king said, “What do you mean?" },
  { zh: "」茅焦曰：「陛下有狂悖之行，不自知邪？", literal: "” Mao Jiao said, “Your Majesty has reckless and perverse conduct—do you not know it?", idiomatic: "” Mao Jiao said, “Your Majesty acts with reckless perversity—do you not know it?" },
  { zh: "車裂假父，囊撲二弟，遷母於雍，殘戮諫士，桀、紂之行不至於是矣。", literal: "You tore apart your false father with chariots, beat your two younger brothers to death in sacks, moved your mother to Yong, and slaughtered remonstrating scholars—Jie and Zhou's conduct did not go this far.", idiomatic: "You had your false father torn apart by chariots, beat your two younger brothers to death in sacks, moved your mother to Yong, and slaughtered remonstrating scholars—even Jie and Zhou did not go this far." },
  { zh: "今天下聞之，盡瓦解，無向秦者，臣竊為陛下危之！", literal: "Now all under Heaven hear of it; all dissolve and disperse—none turn toward Qin. Your servant privately considers Your Majesty in peril!", idiomatic: "Now the world hears of it; all dissolve away—none turn toward Qin. I privately consider Your Majesty in grave peril!" },
  { zh: "臣言已矣！", literal: "Your servant's words are finished!", idiomatic: "I have said my piece!" },
  { zh: "」乃解衣伏質。", literal: "” He then removed his robe and lay down on the execution block.", idiomatic: "” He then stripped and lay down on the block." },
  { zh: "王下殿，手自接之曰：「先生起就衣，今願受事！", literal: "The king descended from the hall, took him by the hand himself, and said, “Master, rise and put on your robe. Now I wish to receive your counsel!", idiomatic: "The king came down from the hall, took him by the hand, and said, “Master, rise and dress. I am ready to hear you!" },
  { zh: "」乃爵之上卿。", literal: "” He then ennobled him as chief minister.", idiomatic: "” He then ennobled him as chief minister." },
  { zh: "王自駕，虛左方，往迎太后，歸於咸陽，復為母子如初。", literal: "The king himself drove the chariot, vacated the seat of honor on the left, went to welcome the queen dowager, returned with her to Xianyang, and mother and son were again as at first.", idiomatic: "The king himself drove, vacated the seat of honor, went to welcome the queen dowager, brought her back to Xianyang, and mother and son were reconciled as before." },
  { zh: "7楚考烈王無子，春申君患之，求婦人宜子者甚眾，進之，卒無子。", literal: "7 King Kaolie of Chu had no son. Lord Chun Shen was troubled by it, sought many women fit to bear sons, and presented them—but in the end there was no son.", idiomatic: "7 King Kaolie of Chu had no son. Lord Chun Shen was troubled, sought many women likely to bear sons, and presented them—yet in the end there was no son." },
  { zh: "趙人李園持其妹欲進諸楚王，聞其不宜子，恐久無寵，乃求為春申君舍人。", literal: "Li Yuan of Zhao, intending to present his younger sister to the king of Chu, heard she was not fit to bear sons and feared that if long without favor she would lose standing; he therefore sought to become a retainer of Lord Chun Shen.", idiomatic: "Li Yuan of Zhao meant to present his sister to the king of Chu but heard she was unlikely to bear sons and feared she would lose favor; he therefore sought to become Lord Chun Shen's retainer." },
  { zh: "已而謁歸，故失期而還。", literal: "After a while he asked leave to return home and deliberately missed the deadline in coming back.", idiomatic: "After a time he asked leave to go home and deliberately returned late." },
  { zh: "春申君問之，李園曰：「齊王使人求臣之妹，與其使者飲，故失期。", literal: "Lord Chun Shen questioned him. Li Yuan said, “The king of Qi sent men to seek your servant's younger sister. Your servant drank with his envoy and therefore missed the deadline.", idiomatic: "Lord Chun Shen questioned him. Li Yuan said, “The king of Qi sent to seek my sister. I drank with his envoy and therefore returned late." },
  { zh: "」春申君曰：「聘入乎？", literal: "” Lord Chun Shen said, “Has the betrothal gift been accepted?", idiomatic: "” Lord Chun Shen said, “Has the betrothal been accepted?" },
  { zh: "」曰：「未也。", literal: "” He said, “Not yet.", idiomatic: "” He said, “Not yet." },
  { zh: "」春申君遂納之。", literal: "” Lord Chun Shen thereupon took her in.", idiomatic: "” Lord Chun Shen thereupon took her in." },
  { zh: "既而有娠，李園使其妹說春申君曰：「楚王貴幸君，雖兄弟不如也。", literal: "Before long she was with child. Li Yuan had his sister persuade Lord Chun Shen, saying, “The king of Chu honors and favors you as none among brothers could.", idiomatic: "Before long she was pregnant. Li Yuan had his sister persuade Lord Chun Shen: “The king of Chu honors you above even his own brothers." },
  { zh: "今君相楚二十餘年而王無子，即百歲後將更立兄弟，彼亦各貴其故所親，君又安得常保此寵乎！", literal: "Now you have been chancellor of Chu for more than twenty years yet the king has no son. When he reaches a hundred years he will establish one of his brothers in turn; they too will each honor their former intimates—how can you always preserve this favor!", idiomatic: "You have governed Chu more than twenty years yet the king has no son. When he dies a brother will succeed; each will favor his own old intimates—how can you always keep this favor!" },
  { zh: "非徒然也，君貴，用事久，多失禮於王之兄弟，兄弟立，禍且及身矣。", literal: "It is not merely that. You are honored and have held power long; you have often been lacking in propriety toward the king's brothers. When a brother is established, calamity will reach your person.", idiomatic: "Worse, you are honored and have held power long; you have often slighted the king's brothers. When a brother succeeds, disaster will reach you." },
  { zh: "今妾有娠而人莫知，妾幸君未久，誠以君之重，進妾於王，王必幸之。", literal: "Now your handmaid is with child and no one knows. Your handmaid has been favored by you not long. If in truth, relying on your weight, you present your handmaid to the king, the king is sure to favor her.", idiomatic: "I am pregnant and no one knows. I have been with you only briefly. If you, in your great standing, present me to the king, he is sure to favor me." },
  { zh: "妾賴天而有男，則是君之子為王也。", literal: "If your handmaid, relying on Heaven, bears a son, then it will be your son who becomes king.", idiomatic: "If Heaven grants me a son, it will be your son who becomes king." },
  { zh: "楚國盡可得，孰與身臨不測之禍哉！", literal: "The whole state of Chu can be obtained—how does that compare with personally facing unforeseen calamity!", idiomatic: "You could hold all Chu—how does that compare with facing unforeseen ruin!" },
  { zh: "」春申君大然之。", literal: "” Lord Chun Shen greatly approved.", idiomatic: "” Lord Chun Shen strongly agreed." },
  { zh: "乃出李園妹，謹舍而言諸楚王。", literal: "He then sent out Li Yuan's sister, lodged her carefully, and spoke of her to the king of Chu.", idiomatic: "He then sent out Li Yuan's sister, lodged her carefully, and recommended her to the king of Chu." },
  { zh: "王召入，幸之，遂生男，立為太子。", literal: "The king summoned her in, favored her, and she bore a son who was established as crown prince.", idiomatic: "The king summoned her, favored her, and she bore a son who was made crown prince." },
  { zh: "李園妹為王后，李園亦貴用事，而恐春申君泄其語，陰養死士，欲殺春申君以滅口；", literal: "Li Yuan's sister became queen; Li Yuan too was honored and held power, yet feared Lord Chun Shen would leak their words; he secretly nurtured bravos who would die and wished to kill Lord Chun Shen to silence him;", idiomatic: "Li Yuan's sister became queen; Li Yuan too rose in honor and power, yet feared Lord Chun Shen would reveal their plot; he secretly kept assassins and meant to kill Lord Chun Shen to silence him;" },
  { zh: "國人頗有知之者。", literal: "among the people of the state quite a few knew of it.", idiomatic: "quite a few in the state knew of it." },
  { zh: "楚王病，朱英謂春申君曰：「世有無望之福，亦有無望之禍。", literal: "The king of Chu fell ill. Zhu Ying said to Lord Chun Shen, “In the world there is unhoped-for fortune, and also unhoped-for calamity.", idiomatic: "The king of Chu fell ill. Zhu Ying said to Lord Chun Shen, “In this world there is fortune one never hoped for, and calamity one never expected." },
  { zh: "今君處無望之世，事無望之主，安可以無無望之人乎！", literal: "Now you dwell in an age of unhoped-for things, serve an unhoped-for lord—how can you be without an unhoped-for man!", idiomatic: "You live in such an age, serve such a lord—how can you be without a man you never expected to need!" },
  { zh: "」春申君曰：「何謂無望之福？", literal: "” Lord Chunshen said, “What is meant by unhoped-for fortune?", idiomatic: "” Lord Chunshen said, “What do you mean by unhoped-for fortune?" },
  { zh: "」曰：「君相楚二十餘年矣，雖名相國，其實王也。", literal: "” He said, “Lord, you have been chancellor of Chu for more than twenty years. Though titled chancellor of state, in reality you are king.", idiomatic: "” He said, “My lord, you have governed Chu as chancellor for more than twenty years. Though you are called chancellor of state, in effect you are king." },
  { zh: "王今病，旦暮薨，薨而君相幼主，因而當國，王長而反政，不即遂南面稱孤，此所謂無望之福也。", literal: "The king is now ill; morning or evening he will die. When he dies you will minister to a young lord and thus hold the state. When the king grows up and takes back government, you will not at once face south and style yourself an independent ruler—this is what is called unhoped-for fortune.", idiomatic: "The king is now ill and may die at any time. When he dies you will serve a young lord and hold the state in your hands—but when the king comes of age and takes back power, you will not at once face south as a sovereign in your own right. That is what is called unhoped-for fortune." },
  { zh: "」「何謂無望之禍？", literal: "”“What is meant by unhoped-for calamity?", idiomatic: "”“What do you mean by unhoped-for calamity?" },
  { zh: "」曰：「李園不治國而君之仇也，不為兵而養死士之日久矣。", literal: "” He said, “Li Yuan does not administer the state yet is your enemy. For a long time he has not raised armies but has been nourishing dare-to-die men.", idiomatic: "” He said, “Li Yuan does not govern the state, yet he is your enemy. For a long time he has kept no army in the field but has been feeding dare-to-die retainers." },
  { zh: "王薨，李園必先入，據權而殺君以滅口，此所謂無望之禍也。", literal: "When the king dies Li Yuan is sure to enter first, seize power, and kill you to silence you—this is what is called unhoped-for calamity.", idiomatic: "When the king dies Li Yuan will surely enter first, seize power, and kill you to silence you—that is what is called unhoped-for calamity." },
  { zh: "」「何謂無望之人？", literal: "”“What is meant by an unhoped-for man?", idiomatic: "”“What do you mean by an unhoped-for man?" },
  { zh: "」曰：「君置臣郎中，王薨，李園先入，臣為君殺之，此所謂無望之人也。", literal: "” He said, “If you appoint me palace attendant, when the king dies and Li Yuan enters first, your servant will kill him for you—this is what is called an unhoped-for man.", idiomatic: "” He said, “Appoint me palace attendant. When the king dies and Li Yuan enters first, I will kill him for you—that is what is called an unhoped-for man." },
  { zh: "」春申君曰：「足下置之。", literal: "” Lord Chunshen said, “Sir, let it be [as you say].", idiomatic: "” Lord Chunshen said, “Very well—consider it done." },
  { zh: "李園，弱人也，僕又善之。", literal: "Li Yuan is a weak man, and I am also on good terms with him.", idiomatic: "Li Yuan is a weak man, and I am on good terms with him besides." },
  { zh: "且何至此！", literal: "Besides, how could it come to that!", idiomatic: "Besides, how could it ever come to that!" },
  { zh: "」朱英知言不用，懼而亡去。", literal: "” Zhu Ying knew his words were not heeded, feared, and fled.", idiomatic: "” Zhu Ying saw his counsel was rejected, feared for his life, and fled." },
  { zh: "後十七日，楚王薨，李園果先入，伏死士於棘門之內。", literal: "Seventeen days later King Chu of Chu died. Li Yuan indeed entered first and hid dare-to-die men inside Jimen Gate.", idiomatic: "Seventeen days later the king of Chu died. Li Yuan did enter first and posted dare-to-die men inside Jimen Gate." },
  { zh: "春申君入，死士俠刺之，投其首於棘門之外；", literal: "Lord Chunshen entered; the dare-to-die men leaned against him and stabbed him, and threw his head outside Jimen Gate;", idiomatic: "Lord Chunshen entered; the assassins closed on him and stabbed him, and threw his head outside Jimen Gate;" },
  { zh: "於是使吏盡捕誅春申君之家。", literal: "thereupon they sent officers to arrest and execute all of Lord Chunshen's household.", idiomatic: "then they sent officers to arrest and execute every member of Lord Chunshen's household." },
  { zh: "太子〔悍〕立<ref>太子〔悍〕立據《史記·楚世家》補。", literal: "The crown prince 〔Huan〕 was established<ref>The crown prince 〔Huan〕 was established—supplemented from the Shiji “House of Chu.”", idiomatic: "The crown prince 〔Huan〕 was enthroned<ref>The crown prince 〔Huan〕 was enthroned—supplemented from the Shiji “House of Chu.”" },
  { zh: "</ref>，是為幽王。", literal: "</ref> who was styled King You.", idiomatic: "</ref> who was styled King You." },
  { zh: "::揚子《法言》曰：或問：「信陵、平原、孟嘗、春申益乎？", literal: ":: Yangzi's Fayan says: Someone asked, “Were Lord Xinling, Lord Pingyuan, Lord Mengchang, and Lord Chunshen beneficial?", idiomatic: ":: Yangzi's Fayan says: Someone asked, “Did Lord Xinling, Lord Pingyuan, Lord Mengchang, and Lord Chunshen do any good?" },
  { zh: "」曰：「上失其政，奸臣竊國命，何其益乎！", literal: "” He said, “The ruler above lost good government; wicked ministers stole the state's mandate—how were they beneficial!", idiomatic: "” He said, “When the ruler above loses good government and wicked ministers steal the mandate of state, how can they be beneficial!" },
  { zh: "8王以文信侯奉先王功大，不忍誅。", literal: "8 The king, because the Lord of Wenxin had rendered great service to the former king, could not bear to execute him.", idiomatic: "8 The king, because the Lord of Wenxin had served the former king with great merit, could not bring himself to execute him." },
  { zh: "1冬，十月，文信侯免相，出就國。", literal: "1 Winter, tenth month: the Lord of Wenxin was dismissed as chancellor and went out to his fief.", idiomatic: "1 In winter, the tenth month, the Lord of Wenxin was removed as chancellor and went to his fief." },
  { zh: "宗室大臣議曰：「諸侯人來仕者，皆為其主游間耳，請一切逐之。", literal: "The royal clansmen and great ministers deliberated, saying, “Men who come from feudal states to serve all engage in secret diplomacy for their lords—pray expel them all.", idiomatic: "The royal clansmen and great ministers debated, saying, “Every man who comes from another state to serve does secret diplomacy for his own lord—let us expel them all." },
  { zh: "」於是大索，逐客。", literal: "” Thereupon a great search was made and guests were expelled.", idiomatic: "” Thereupon a thorough search was made and all foreign retainers were expelled." },
  { zh: "客卿楚人李斯亦在逐中，行，且上書曰：「昔穆公求士，西取由余於戎，東得百里〔奚〕於宛，迎蹇叔於宋，求丕豹、公孫支於晉，併國二十，遂霸西戎。", literal: "Guest minister Li Si, a man of Chu, was also among those expelled. As he traveled he drafted a memorial, saying, “Formerly Duke Mu sought worthies: westward he took You Yu from the Rong; eastward he obtained Baili 〔Xi〕 at Wan; he welcomed Jian Shu at Song; from Jin he sought Pi Bao and Gongsun Zhi—he annexed twenty states and then hegemonized the western Rong.", idiomatic: "The guest minister Li Si of Chu was among those expelled. On the road he drafted a memorial, saying, “Formerly Duke Mu sought men of talent: westward he took You Yu from the Rong; eastward he found Baili 〔Xi〕 at Wan; he welcomed Jian Shu from Song; from Jin he obtained Pi Bao and Gongsun Zhi—he annexed twenty states and became hegemon over the western Rong." },
  { zh: "孝公用商鞅之法，諸侯親服，至今治強。", literal: "Duke Xiao employed Lord Shang's laws; the feudal lords drew near and submitted, and to this day government is strong.", idiomatic: "Duke Xiao employed Shang Yang's laws; the feudal lords submitted, and to this day Qin remains strong and well governed." },
  { zh: "惠王用張儀之計，散六國之從，使之事秦。", literal: "King Hui employed Zhang Yi's plans, broke up the Six States' vertical alliance, and made them serve Qin.", idiomatic: "King Hui employed Zhang Yi's stratagems, broke up the vertical alliance of the six states, and made them serve Qin." },
  { zh: "昭王得范睢，強公室，杜私門。", literal: "King Zhao obtained Fan Ju, strengthened the ducal house, and shut the private gates.", idiomatic: "King Zhao obtained Fan Ju, strengthened the royal house, and closed off private factions." },
  { zh: "此四君者，皆以客之功。", literal: "These four rulers all achieved it through the merit of guests.", idiomatic: "These four rulers all owed their success to foreign retainers." },
  { zh: "由此觀之，客何負於秦哉！", literal: "From this perspective, what have guests done wrong to Qin!", idiomatic: "Seen in this light, what offense have guests committed against Qin!" },
  { zh: "夫色、樂、珠、玉不產於秦而王服御者眾，取人則不然，不問可否，不論曲直，非秦者去，為客者逐。", literal: "Now colors, music, pearls, and jade are not produced in Qin yet Your Majesty's attire and use of them are many; yet in taking men it is not so—you do not ask whether they are fit, you do not weigh right and wrong: those not of Qin are removed, and those who are guests are expelled.", idiomatic: "Colors, music, pearls, and jade do not come from Qin, yet Your Majesty uses them in abundance; but in choosing men you do the opposite—you do not ask whether they are fit, you do not weigh right and wrong: anyone not from Qin is rejected, and every guest is driven away." },
  { zh: "是所重者在乎色、樂、珠、玉，而所輕者在乎人民也。", literal: "This is to value colors, music, pearls, and jade, and to slight the people.", idiomatic: "This means you value colors, music, pearls, and jade, and slight the people." },
  { zh: "臣聞泰山不讓土壤，故能成其大；", literal: "Your servant has heard that Mount Tai does not reject soil, and therefore can achieve its greatness;", idiomatic: "I have heard that Mount Tai does not reject even a handful of soil, and therefore grows great;" },
  { zh: "河海不擇細流，故能就其深；", literal: "rivers and seas do not choose among small streams, and therefore can achieve their depth;", idiomatic: "rivers and seas do not refuse the smallest stream, and therefore grow deep;" },
  { zh: "王者不卻眾庶，故能明其德。", literal: "a true king does not turn away the multitude, and therefore can illumine his virtue.", idiomatic: "a true king does not turn the common people away, and therefore can make his virtue shine." },
  { zh: "此五帝、三王之所以無敵也。", literal: "This is why the Five Emperors and Three Kings were without peer.", idiomatic: "That is why the Five Emperors and Three Kings had no equals." },
  { zh: "今乃棄黔首以資敵國，卻賓客以業諸侯，所謂藉寇兵而賚盜糧者也。", literal: "Now you cast aside the black-haired people to enrich enemy states and turn away guests to build up the feudal lords—this is what is called lending weapons to bandits and feeding grain to thieves.", idiomatic: "Now you cast off the common people to enrich enemy states and turn guests away to strengthen the feudal lords—this is what people call arming bandits and feeding grain to thieves." },
  { zh: "」王乃召李斯，復其官，除逐客之令。", literal: "” The king then summoned Li Si, restored his office, and abolished the order expelling guests.", idiomatic: "” The king then summoned Li Si, restored him to office, and revoked the order expelling guests." },
  { zh: "李斯至驪邑而還。", literal: "Li Si reached Liyi and returned.", idiomatic: "Li Si had reached Liyi when he was recalled." },
  { zh: "王卒用李斯之謀，陰遣辯士齎金玉遊說諸侯，諸侯名士可下以財者厚遺結之，不肯者利劍刺之，離其君臣之計，然後使良將隨其後，數年之中，卒兼天下。", literal: "The king in the end employed Li Si's stratagem: secretly he sent eloquent men bearing gold and jade to lobby the feudal lords; famous men of the states who could be won with wealth he bound with lavish gifts, and those who would not submit he had stabbed with sharp swords. He sundered their plans between ruler and minister, then sent fine generals after them—in several years he finally united all under Heaven.", idiomatic: "The king at last adopted Li Si's plan: secretly he sent persuaders with gold and jade to work on the feudal lords; eminent men who could be bought he won with lavish gifts, and those who refused he had killed with the sword. He broke apart their rulers and ministers, then sent able generals in their wake—and within a few years he had united the empire." },
  { zh: "1趙人伐燕，取貍、陽〔城〕<ref>取貍、陽〔城〕據《史記·趙世家》補。", literal: "1 The men of Zhao attacked Yan and took Li and Yang 〔cheng〕<ref>Took Li and Yang 〔cheng〕—supplemented from the Shiji “House of Zhao.”", idiomatic: "1 Zhao attacked Yan and took Li and Yang 〔cheng〕<ref>Took Li and Yang 〔cheng〕—supplemented from the Shiji “House of Zhao.”" },
  { zh: "正義以「貍陽」二字連讀，並認為當作漁陽，胡注同，實誤。", literal: "Zhengyi reads the two characters “Li-Yang” together and holds they should be Yuyang; Hu's note agrees—this is in fact an error.", idiomatic: "Zhengyi reads “Li-Yang” as one place-name and thinks it should be Yuyang; Hu's commentary agrees—both are mistaken." },
  { zh: "案：貍，《韓非子·飾邪篇》作「釐」，音同通同。", literal: "Examination: for Li, the “Adorning the Wicked” chapter of the Han Feizi writes 釐; the sounds are the same and the graphs are interchangeable.", idiomatic: "Examination: for Li, Han Feizi's “Adorning the Wicked” writes 釐; the two graphs are phonetically equivalent and interchangeable." },
  { zh: "貍在今河北任丘縣東北，陽城在今河北保定市北。", literal: "Li is northeast of present-day Renqiu county in Hebei; Yangcheng is north of present-day Baoding city in Hebei.", idiomatic: "Li lay northeast of present Renqiu in Hebei; Yangcheng lay north of present Baoding in Hebei." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "兵未罷，將軍王翦、桓齮、楊端和伐趙，攻鄴，取九城。", literal: "Before the army was dismissed, the generals Wang Jian, Huan Yi, and Yang Duanhe attacked Zhao, assaulted Ye, and took nine cities.", idiomatic: "Before those troops were withdrawn, the generals Wang Jian, Huan Yi, and Yang Duanhe attacked Zhao, assaulted Ye, and took nine cities." },
  { zh: "王翦攻閼與、轑陽，桓齮取鄴、安陽。", literal: "Wang Jian attacked Heyu and Liaoyang; Huan Yi took Ye and Anyang.", idiomatic: "Wang Jian attacked Heyu and Liaoyang; Huan Yi took Ye and Anyang." },
  { zh: "2趙悼襄王薨，子幽繆王遷立。", literal: "2 King Daoxiang of Zhao died; his son King Youmiao Qian was established.", idiomatic: "2 King Daoxiang of Zhao died; his son Qian was enthroned as King Youmiao." },
  { zh: "其母，倡也，嬖於悼襄王，悼襄王廢嫡子嘉而立之。", literal: "His mother was a singing girl, favored by King Daoxiang; King Daoxiang deposed the legitimate son Jia and established him.", idiomatic: "His mother was a courtesan favored by King Daoxiang, who set aside the legitimate heir Jia and enthroned Qian instead." },
  { zh: "遷素以無行聞於國。", literal: "Qian had long been known in the state for want of conduct.", idiomatic: "Qian had long been known throughout the state for his bad conduct." },
  { zh: "3文信侯就國歲餘，諸侯賓客使者相望於道，請之。", literal: "3 The Lord of Wenxin had been at his fief more than a year; guests and envoys from the feudal lords lined the road asking for him.", idiomatic: "3 More than a year after the Lord of Wenxin went to his fief, guests and envoys from the feudal lords thronged the roads petitioning on his behalf." },
  { zh: "王恐其為變，乃賜文信侯書曰：「君何功於秦，封君河南，食十萬戶？", literal: "The king feared he might rebel and therefore sent the Lord of Wenxin a letter, saying, “What merit have you toward Qin, that we enfeoffed you in Henan with a revenue of one hundred thousand households?", idiomatic: "The king feared he might stir up trouble and sent the Lord of Wenxin a letter, saying, “What service have you done Qin that we enfeoffed you in Henan with a revenue of one hundred thousand households?" },
  { zh: "何親於秦，號稱仲父？", literal: "What kinship have you with Qin, that we styled you Zhongfu?", idiomatic: "What tie of kinship do you have with Qin that we styled you Zhongfu, ‘father-by-protocol’?" },
  { zh: "其與家屬徙處蜀！", literal: "Go with your household and relocate to Shu!", idiomatic: "Take your household and move to Shu!" },
  { zh: "」文信侯自知稍侵，恐誅。", literal: "” The Lord of Wenxin knew himself increasingly encroached upon and feared execution.", idiomatic: "” The Lord of Wenxin knew his position was slipping away and feared he would be put to death." },
  { zh: "1文信侯飲酖死，竊葬。", literal: "1 The Lord of Wenxin drank poison and died; he was buried secretly.", idiomatic: "1 The Lord of Wenxin drank poison and died; he was buried in secret." },
  { zh: "其舍人臨者，皆逐遷之。", literal: "His retainers who attended him were all expelled and relocated.", idiomatic: "Every retainer who had attended him was expelled and banished." },
  { zh: "且曰：「自今以來，操國事不道如嫪毐、不韋者，籍其門，視此！", literal: "It was also said, “From now on, whoever handles state affairs wickedly like Lao Ai or Buwei—register his household and look to this!", idiomatic: "The order also ran, “From this day forward, whoever wields state power as wickedly as Lao Ai or Lü Buwei—register his household and take this as your warning!" },
  { zh: "::揚子《法言》曰：或問：「呂不韋其智矣乎？", literal: ":: Yangzi's Fayan says: Someone asked, “Was Lü Buwei wise?", idiomatic: ":: Yangzi's Fayan says: Someone asked, “Was Lü Buwei wise?" },
  { zh: "以人易貨。", literal: "He traded goods for a man.", idiomatic: "He traded goods for a man." },
  { zh: "」曰：「誰謂不韋智者歟？", literal: "” He said, “Who says Buwei was wise?", idiomatic: "” He said, “Who calls Buwei wise?" },
  { zh: "以國易宗。", literal: "He traded the state for his clan.", idiomatic: "He traded the state for his clan." },
  { zh: "呂不韋之盜，穿窬之雄乎！", literal: "Lü Buwei's thievery—was he not a champion among wall-burglars!", idiomatic: "Lü Buwei's theft—was he not king of housebreakers!" },
  { zh: "穿窬也者，吾見擔石矣，未見雒陽也。", literal: "As for wall-burglars, I have seen them carry off bushels and stones, but I have not seen them carry off Luoyang.", idiomatic: "Housebreakers, I have seen, carry off bushels of grain; I have never seen one carry off Luoyang." },
  { zh: "2自六月不雨，至於八月。", literal: "2 From the sixth month there was no rain until the eighth month.", idiomatic: "2 From the sixth month there was no rain until the eighth month." },
  { zh: "3發四郡兵助魏伐楚。", literal: "3 Four commanderies' troops were mobilized to help Wei attack Chu.", idiomatic: "3 Troops from four commanderies were sent to help Wei attack Chu." },
  { zh: "1桓齮伐趙，敗趙將扈棷於平陽，斬首十萬，殺扈棷。", literal: "1 Huan Yi attacked Zhao, defeated Zhao's general Hu Qi at Pingyang, beheaded one hundred thousand, and killed Hu Qi.", idiomatic: "1 Huan Yi attacked Zhao, defeated the Zhao general Hu Qi at Pingyang, beheaded one hundred thousand men, and killed Hu Qi." },
  { zh: "〔冬，十月，桓齮復伐趙〕<ref>〔冬十月桓齮復伐趙〕據《史記·秦始皇本紀》補。", literal: "〔Winter, tenth month, Huan Yi again attacked Zhao〕<ref>〔Winter, tenth month, Huan Yi again attacked Zhao〕—supplemented from the Shiji “Basic Annals of Qin Shihuang.”", idiomatic: "〔Winter, tenth month, Huan Yi again attacked Zhao〕<ref>〔Winter, tenth month, Huan Yi again attacked Zhao〕—supplemented from the Shiji “Basic Annals of Qin Shihuang.”" },
  { zh: "舊文下有「趙王以李牧為大將軍」等三十二字，據《史記·趙世家》移往後年，並刪「復」字。", literal: "The old text below had thirty-two characters such as “the king of Zhao made Li Mu grand general”; per the Shiji “House of Zhao” they were moved to a later year, and the character “again” was deleted.", idiomatic: "The old text below contained thirty-two characters such as “the king of Zhao made Li Mu grand general”; following the Shiji “House of Zhao” they were moved to a later year, and the word “again” was deleted." },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1桓齮伐趙，〔殺其趙將〕<ref>〔殺其趙將〕據《史記·秦始皇本紀》補。", literal: "1 Huan Yi attacked Zhao, 〔and killed its Zhao general〕<ref>〔And killed its Zhao general〕—supplemented from the Shiji “Basic Annals of Qin Shihuang.”", idiomatic: "1 Huan Yi attacked Zhao, 〔and killed its Zhao general〕<ref>〔And killed its Zhao general〕—supplemented from the Shiji “Basic Annals of Qin Shihuang.”" },
  { zh: "</ref>，取宜安、平陽、武城。", literal: "</ref> and took Yi'an, Pingyang, and Wucheng.", idiomatic: "</ref> and took Yi'an, Pingyang, and Wucheng." },
  { zh: "〔趙王以李牧為大將軍，戰於宜安、肥下，秦師敗績，桓齮奔還。", literal: "〔The king of Zhao made Li Mu grand general. They fought at Yi'an and below Fei; the Qin army was routed and Huan Yi fled back.", idiomatic: "〔The king of Zhao made Li Mu grand general. They fought at Yi'an and below Fei; the Qin army was routed and Huan Yi fled home." },
  { zh: "趙封李牧為武安君〕。", literal: "Zhao enfeoffed Li Mu as Lord of Wu'an.〕", idiomatic: "Zhao enfeoffed Li Mu as Lord of Wu'an.〕" },
  { zh: "2韓王納地效璽，請為籓臣，使韓非來聘。", literal: "2 The king of Han surrendered territory and presented his seal, asked to become a vassal, and sent Han Fei on a friendly mission.", idiomatic: "2 The king of Han surrendered territory and presented his seal, asked to become a vassal, and sent Han Fei on a diplomatic visit." },
  { zh: "韓非者，韓之諸公子也，善刑名法術之學，見韓之削弱，數以書干韓王，王不能用。", literal: "Han Fei was a cadet son of Han, skilled in the learning of penal names and legal arts. Seeing Han's weakening, he repeatedly submitted memorials to the king of Han, but the king could not employ him.", idiomatic: "Han Fei was a prince of the house of Han, versed in the school of penal law and statecraft. Seeing Han grow weak, he repeatedly submitted memorials to the king of Han, but the king would not use him." },
  { zh: "於是韓非疾治國不務求人任賢，反舉浮淫之蠹而加之功實之上，寬則寵名譽之人，急則用介冑之士，所養非所用，所用非所養。", literal: "Thereupon Han Fei grieved that in governing the state men did not seek out and employ the worthy, but instead raised floating, licentious parasites and set them above those of real achievement; in lax times they favored men of empty reputation, in urgent times they used men in armor—their nurtures were not their employs, their employs were not their nurtures.", idiomatic: "Han Fei lamented that in governing the state they did not seek out and employ the worthy, but instead promoted worthless parasites above men of real achievement; in easy times they favored men of empty reputation, in crisis they used armored soldiers—those they cultivated were not those they used, and those they used were not those they cultivated." },
  { zh: "悲廉直不容於邪枉之臣，觀往者得失之變，作《孤憤》、《五蠹》、《內外儲》、《說林》、《說難》五十六篇，十餘萬言。", literal: "Grieving that the upright and honest found no place among crooked ministers, he observed how past gain and loss shifted and composed fifty-six chapters—“Solitary Indignation,” “Five Vermin,” “Inner and Outer Stores,” “Forest of Persuasions,” and “Difficulties of Persuasion”—more than one hundred thousand words.", idiomatic: "Grieving that honest men found no room among crooked ministers, he studied how past successes and failures had shifted and wrote fifty-six chapters—“Solitary Indignation,” “Five Vermin,” “Inner and Outer Stores,” “Forest of Persuasions,” and “Difficulties of Persuasion”—more than one hundred thousand words in all." },
  { zh: "王聞其賢，欲見之。", literal: "The king heard of his worth and wished to see him.", idiomatic: "The king of Qin heard he was worthy and wished to meet him." },
  { zh: "非為韓使於秦，因上書說王曰：「今秦地方數千里，師名百萬，號令賞罰，天下不如。", literal: "Han Fei came as Han's envoy to Qin and therefore submitted a memorial persuading the king, saying, “Now Qin's territory spans several thousand li, its army and fame reach one million, and in commands, rewards, and punishments none under Heaven compares.", idiomatic: "Han Fei came to Qin as Han's envoy and submitted a memorial urging the king, saying, “Qin today holds several thousand li of territory, commands an army a million strong, and in orders, rewards, and punishments has no equal under Heaven." },
  { zh: "臣昧死願望見大王，言所以破天下從之計。", literal: "Your servant, risking death, wishes to be granted an audience with Your Great Majesty to speak of the plan for breaking the vertical alliance of all under Heaven.", idiomatic: "I beg leave, at the risk of my life, to be granted an audience so I may explain how to break the vertical alliance of the empire." },
  { zh: "大王誠聽臣說，一舉而天下之從不破，趙不舉，韓不亡，荊、魏不臣，齊、燕不親，霸王之名不成，四鄰諸侯不朝，大王斬臣以徇國，以戒為王謀不忠者也。", literal: "If Your Great Majesty truly heeds your servant's persuasion, with one stroke the world's vertical alliance will not stand unbroken—if Zhao is not taken, Han is not destroyed, Jing and Wei do not submit, Qi and Yan do not draw near, the name of hegemon-king is not achieved, and the four neighboring feudal lords do not attend court, then let Your Great Majesty execute your servant to display throughout the state, as a warning to those who counsel the king without loyalty.", idiomatic: "If Your Majesty truly heeds my counsel, one stroke will break the vertical alliance—if Zhao is not taken, Han is not destroyed, Chu and Wei do not submit, Qi and Yan are not won over, the title of hegemon is not achieved, and the neighboring feudal lords do not come to court, then execute me before the nation as a warning to disloyal counselors." },
  { zh: "」王悅之，未任用。", literal: "” The king was pleased with him but did not employ him.", idiomatic: "” The king was pleased but did not appoint him." },
  { zh: "李斯嫉之，曰：「韓非，韓之諸公子也。", literal: "Li Si envied him and said, “Han Fei is a cadet son of Han.", idiomatic: "Li Si envied him and said, “Han Fei is a prince of Han." },
  { zh: "今欲並諸侯，非終為韓不為秦，此人情也。", literal: "Now you wish to annex the feudal lords—Han Fei in the end will serve Han and not Qin; this is human nature.", idiomatic: "Now you mean to annex the feudal lords—Han Fei will in the end serve Han, not Qin; that is only human nature." },
  { zh: "今王不用，又留而歸之，此自遺患也。", literal: "Now if the king does not use him yet keeps him and sends him home, this is to bequeath trouble on oneself.", idiomatic: "If Your Majesty does not use him but keeps him and then sends him home, you will be storing up trouble for yourself." },
  { zh: "不如以法誅之。", literal: "Better to punish him by law.", idiomatic: "Better to put him to death according to law." },
  { zh: "」王以為然，下吏治非。", literal: "” The king thought it right and handed him to the officials to try Han Fei.", idiomatic: "” The king agreed and handed Han Fei over to the officials for trial." },
  { zh: "李斯使人遺非藥，令早自殺。", literal: "Li Si sent a man to present Han Fei with poison and ordered him to kill himself soon.", idiomatic: "Li Si sent a man to give Han Fei poison and told him to take his own life quickly." },
  { zh: "韓非欲自陳，不得見。", literal: "Han Fei wished to plead in person but could not obtain an audience.", idiomatic: "Han Fei wished to plead his case in person but was denied an audience." },
  { zh: "王後悔，使赦之，非已死矣。", literal: "The king afterward regretted it and sent to pardon him, but Han Fei was already dead.", idiomatic: "The king later regretted it and sent a pardon, but Han Fei was already dead." },
  { zh: "::揚子《法言》曰：或問：「韓非作《說難》之書而卒死乎說難，敢問何反也？", literal: ":: Yangzi's Fayan says: Someone asked, “Han Fei wrote the book ‘Difficulties of Persuasion’ and in the end died in the difficulty of persuasion—dare I ask, how was this contrary?", idiomatic: ":: Yangzi's Fayan says: Someone asked, “Han Fei wrote ‘Difficulties of Persuasion’ and in the end died in the difficulty of persuasion—may I ask how this squares?" },
  { zh: "」曰：「《說難》蓋其所以死乎！", literal: "” He said, “‘Difficulties of Persuasion’ was probably the very reason he died!", idiomatic: "” He said, “‘Difficulties of Persuasion’ was probably exactly why he died!" },
  { zh: "」曰：「何也？", literal: "” He said, “How so?", idiomatic: "” He said, “How so?" },
  { zh: "」「君子以禮動，以義止，合則進，否則退，確乎不憂其不合也。", literal: "”“The gentleman moves by ritual and stops by righteousness; if it fits he advances, if not he withdraws—steadfastly he does not worry that it will not fit.", idiomatic: "”“The gentleman acts through ritual and stops through righteousness; if the fit is right he advances, if not he withdraws—firmly without fretting that he may not be accepted." },
  { zh: "夫說人而憂其不合，則亦無所不至矣。", literal: "Now one who persuades others yet worries that they will not fit—then there is nothing he will not stoop to.", idiomatic: "But one who persuades others yet frets that they will not accept him—there is nothing he will not do." },
  { zh: "」或曰：「非憂說之不合，非邪？", literal: "” Someone said, “Was it not that Han Fei worried persuasion would not fit—not so?", idiomatic: "” Someone said, “Surely Han Fei did not worry that persuasion would fail—did he?" },
  { zh: "」曰：「說不由道，憂也。", literal: "” He said, “To persuade not by the Way—that is what to worry about.", idiomatic: "” He said, “To worry when persuasion departs from the Way—that is the worry." },
  { zh: "由道而不合，非憂也。", literal: "To persuade by the Way yet not fit—that is not a worry.", idiomatic: "To persuade by the Way and yet fail—that is no worry." },
  { zh: "::臣光曰：臣聞君子親其親以及人之親，愛其國以及人之國，是以功大名美而享有百福也。", literal: ":: Your servant Guang says: Your servant has heard that the gentleman treats his own kin and extends it to others' kin, loves his own state and extends it to others' states—therefore his merit is great, his name is fair, and he enjoys a hundred blessings.", idiomatic: ":: Your servant Guang says: I have heard that the gentleman honors his own kin and extends that honor to others' kin, loves his own state and extends that love to others' states—therefore his merit is great, his fame fair, and he enjoys every blessing." },
  { zh: "今非為秦畫謀，而首欲覆其宗國，以售其言，罪固不容於死矣，烏足愍哉！", literal: "Now Han Fei plotted for Qin yet above all wished to overturn his ancestral state to sell his words—his offense truly could not be contained short of death; how was he worth pitying!", idiomatic: "Yet Han Fei, while plotting for Qin, above all sought to destroy his own ancestral state to sell his counsel—his crime truly deserved death; how was he worth pity!" },
  { zh: "1王大興師伐趙，一軍抵鄴，一軍抵太原，取狼孟(", literal: "1 The king raised a great army to attack Zhao; one army reached Ye, one reached Taiyuan, and took Langmeng (", idiomatic: "1 The king raised a great army against Zhao; one force reached Ye, one reached Taiyuan, and took Langmeng (" },
  { zh: "番吾)", literal: "Fanwu)", idiomatic: "Fanwu)" },
  { zh: "遇李牧〔於番吾，秦師敗〕(", literal: "met Li Mu 〔at Fanwu; the Qin army was defeated〕 (", idiomatic: "met Li Mu 〔at Fanwu; the Qin army was defeated〕 (" },
  { zh: "而)", literal: "and)", idiomatic: "and)" },
  { zh: "還<ref>取狼孟(", literal: "returned<ref>took Langmeng (", idiomatic: "returned<ref>took Langmeng (" },
  { zh: "番吾)", literal: "Fanwu)", idiomatic: "Fanwu)" },
  { zh: "遇李牧〔於番吾，秦師敗〕(", literal: "met Li Mu 〔at Fanwu; the Qin army was defeated〕 (", idiomatic: "met Li Mu 〔at Fanwu; the Qin army was defeated〕 (" },
  { zh: "而)", literal: "and)", idiomatic: "and)" },
  { zh: "還據《史記·趙世家》及《李牧傳》改。", literal: "returned—amended per the “Hereditary House of Zhao” and “Biography of Li Mu” in the Shiji.", idiomatic: "returned—amended per the Shiji “Hereditary House of Zhao” and “Biography of Li Mu.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "2初，燕太子丹嘗質於趙，與王善。", literal: "2 Earlier, Crown Prince Dan of Yan had once been a hostage in Zhao and was on good terms with the king.", idiomatic: "2 Earlier, Crown Prince Dan of Yan had once been a hostage in Zhao and was on good terms with the king." },
  { zh: "王即位，丹為質於秦，王不禮焉。", literal: "When the king took the throne, Dan was a hostage in Qin, and the king did not treat him with courtesy.", idiomatic: "When the king took the throne, Dan was a hostage in Qin, and the king did not treat him courteously." },
  { zh: "丹怒，亡歸。", literal: "Dan was angry and fled home.", idiomatic: "Dan in anger fled home." },
  { zh: "1韓獻南陽地。", literal: "1 Han presented the Nanyang territory.", idiomatic: "1 Han ceded the Nanyang territory." },
  { zh: "〔秋〕，九月<ref>〔秋〕九月據《通鑑》通例補</ref>，發卒受地於韓。", literal: "〔Autumn〕, ninth month<ref>〔Autumn〕, ninth month supplemented per Zizhi Tongjian convention</ref>, troops were mobilized to receive the territory from Han.", idiomatic: "〔Autumn〕, ninth month<ref>〔Autumn〕, ninth month supplemented per Zizhi Tongjian convention</ref>, troops were mobilized to take over the territory from Han." },
  { zh: "2魏人獻地。", literal: "2 The people of Wei presented territory.", idiomatic: "2 Wei ceded territory." },
  { zh: "3代地震，自樂徐以西，北至平陰；", literal: "3 Dai was shaken by earthquake, from Leyang-Xu westward, north to Pingyin;", idiomatic: "3 Dai was struck by earthquake, from Leyang-Xu westward as far north as Pingyin;" },
  { zh: "臺屋牆垣太半壞，地坼東西百三十步。", literal: "platforms, houses, and walls were mostly destroyed; the ground split east and west one hundred thirty paces.", idiomatic: "platforms, houses, and walls were mostly destroyed; the ground split one hundred thirty paces east to west." },
  { zh: "1內史〔騰〕(", literal: "1 The Inner Administrator 〔Teng〕 (", idiomatic: "1 The Inner Administrator 〔Teng〕 (" },
  { zh: "勝)", literal: "Sheng)", idiomatic: "Sheng)" },
  { zh: "滅韓<ref>內史〔騰〕(", literal: "destroyed Han<ref>The Inner Administrator 〔Teng〕 (", idiomatic: "destroyed Han<ref>The Inner Administrator 〔Teng〕 (" },
  { zh: "勝)", literal: "Sheng)", idiomatic: "Sheng)" },
  { zh: "滅韓據《史記·秦始皇本紀》改。", literal: "destroyed Han—amended per the “Basic Annals of Qin Shihuang” in the Shiji.", idiomatic: "destroyed Han—amended per the Shiji “Basic Annals of Qin Shihuang.”" },
  { zh: "</ref>，虜韓王安，以其地置潁川郡。", literal: "</ref>, captured King An of Han, and on his territory established Yingchuan commandery.", idiomatic: "</ref>, captured King An of Han, and on his lands established Yingchuan commandery." },
  { zh: "2華陽太后薨。", literal: "2 Queen Dowager Huayang died.", idiomatic: "2 Queen Dowager Huayang died." },
  { zh: "3趙大饑。", literal: "3 Great famine in Zhao.", idiomatic: "3 Great famine in Zhao." },
  { zh: "4衛元君薨，子角立。", literal: "4 Lord Yuan of Wei died; his son Jiao was established.", idiomatic: "4 Lord Yuan of Wei died; his son Jiao succeeded." },
  { zh: "1王翦將上地，兵下井陘，〔羌瘣將囗囗兵，楊〕端和將河內兵<ref>〔羌瘣將囗囗兵楊〕端和將河內兵據胡注及《史記·秦始皇本紀》補。", literal: "1 Wang Jian commanded Shang commandery; his army descended through Jingxing. 〔Qiang Lei commanded □□ troops; Yang〕 Duanhe commanded the Henei army<ref>〔Qiang Lei commanded □□ troops; Yang〕 Duanhe commanded the Henei army—supplemented per Hu's commentary and the “Basic Annals of Qin Shihuang” in the Shiji.", idiomatic: "1 Wang Jian commanded Shang and led his army down through Jingxing. 〔Qiang Lei commanded □□ troops; Yang〕 Duanhe commanded the Henei army<ref>〔Qiang Lei commanded □□ troops; Yang〕 Duanhe commanded the Henei army—supplemented per Hu's commentary and the Shiji “Basic Annals of Qin Shihuang.”" },
  { zh: "按《史記》不言羌瘣將某地，當有奪誤。", literal: "Examination: the Shiji does not say where Qiang Lei commanded troops; there must be a lacuna or error.", idiomatic: "Note: the Shiji does not say where Qiang Lei commanded troops; text has surely been lost or garbled." },
  { zh: "是年秦分三路進軍攻趙，楊端和圍趙都，而王翦、羌瘣入定地也。", literal: "That year Qin advanced against Zhao in three columns: Yang Duanhe besieged the capital of Zhao, while Wang Jian and Qiang Lei subdued the settled lands.", idiomatic: "That year Qin attacked Zhao in three columns: Yang Duanhe besieged the Zhao capital, while Wang Jian and Qiang Lei subdued the heartland." },
  { zh: "《通鑑》刪羌瘣，非也，據補。", literal: "The Comprehensive Mirror deleted Qiang Lei—incorrect; restored accordingly.", idiomatic: "The Comprehensive Mirror omitted Qiang Lei—wrong; restored accordingly." },
  { zh: "</ref>，共伐趙。", literal: "</ref>, and together they attacked Zhao.", idiomatic: "</ref>, and together they attacked Zhao." },
  { zh: "趙李牧、司馬尚禦之。", literal: "Li Mu and Sima Shang of Zhao defended against them.", idiomatic: "Li Mu and Sima Shang of Zhao held them off." },
  { zh: "秦人多與趙王嬖臣郭開金，使毀牧及尚，言其欲反。", literal: "Many men of Qin gave gold to the king of Zhao's favored minister Guo Kai and had him slander Li Mu and Shang, saying they wished to rebel.", idiomatic: "Many Qin agents bribed the king of Zhao's favorite Guo Kai to slander Li Mu and Shang, claiming they planned rebellion." },
  { zh: "趙王使趙蔥及齊將顏聚代之。", literal: "The king of Zhao sent Zhao Cong and Yan Ju, a general of Qi, to replace them.", idiomatic: "The king of Zhao sent Zhao Cong and the Qi general Yan Ju to replace them." },
  { zh: "李牧不受命，趙人捕而殺之；", literal: "Li Mu did not accept the command; men of Zhao captured and killed him;", idiomatic: "Li Mu refused the command; Zhao men seized and killed him;" },
  { zh: "廢司馬尚。", literal: "and dismissed Sima Shang.", idiomatic: "and dismissed Sima Shang." },
  { zh: "〔翦擊趙軍，大破之，殺趙蔥，顏聚亡，遂圍邯鄲〕<ref>〔翦擊趙軍，大破之，殺趙蔥，顏聚亡，遂圍邯鄲〕此十七字原繫於始皇帝十九年，據《史記·趙世家》及《李牧傳》移往本年，並改「克」為「圍」。", literal: "〔Wang Jian struck the Zhao army, routed it utterly, killed Zhao Cong, Yan Ju fled, and thereafter besieged Handan〕<ref>〔Wang Jian struck the Zhao army, routed it utterly, killed Zhao Cong, Yan Ju fled, and thereafter besieged Handan〕—these seventeen characters originally belonged to the nineteenth year of the First Emperor; moved to this year per the “Hereditary House of Zhao” and “Biography of Li Mu” in the Shiji, and “captured” was changed to “besieged.”", idiomatic: "〔Wang Jian struck the Zhao army, routed it, killed Zhao Cong, Yan Ju fled, and then besieged Handan〕<ref>〔Wang Jian struck the Zhao army, routed it, killed Zhao Cong, Yan Ju fled, and then besieged Handan〕—these seventeen characters originally stood under the nineteenth year of the First Emperor; moved here per the Shiji “Hereditary House of Zhao” and “Biography of Li Mu,” with “captured” changed to “besieged.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "1〔冬，十月〕<ref>〔冬十月〕據《史記·趙世家》補。", literal: "1 〔Winter, tenth month〕<ref>〔Winter, tenth month〕 supplemented per the “Hereditary House of Zhao” in the Shiji.", idiomatic: "1 〔Winter, tenth month〕<ref>〔Winter, tenth month〕 supplemented per the Shiji “Hereditary House of Zhao.”" },
  { zh: "</ref>，克邯鄲，虜趙王遷，〔盡定趙地〕<ref>〔盡定趙地〕據《史記·王翦列傳》補。", literal: "</ref>, captured Handan and took King Qian of Zhao prisoner. 〔All Zhao territory was settled〕<ref>〔All Zhao territory was settled〕 supplemented per the “Biography of Wang Jian” in the Shiji.", idiomatic: "</ref>, took Handan and captured King Qian of Zhao. 〔All Zhao was pacified〕<ref>〔All Zhao was pacified〕 supplemented per the Shiji “Biography of Wang Jian.”" },
  { zh: "</ref>。", literal: "</ref>.", idiomatic: "</ref>." },
  { zh: "王如邯鄲，故與母家有仇怨者皆殺之。", literal: "The king went to Handan; all who had old grudges against his mother's family were killed.", idiomatic: "The king went to Handan and killed everyone who had old scores against his mother's kin." },
  { zh: "還，從太原、上郡歸。", literal: "Returning, he came back by way of Taiyuan and Shang commandery.", idiomatic: "On his return he came back through Taiyuan and Shang." },
  { zh: "2太后薨。", literal: "2 The queen dowager died.", idiomatic: "2 The queen dowager died." },
  { zh: "3王翦屯中山以臨燕。", literal: "3 Wang Jian encamped at Zhongshan to threaten Yan.", idiomatic: "3 Wang Jian encamped at Zhongshan to menace Yan." },
  { zh: "趙公子嘉帥其宗族數百人奔代，自立為代王，趙之亡，大夫稍稍歸之，與燕合兵，軍上谷。", literal: "The prince of Zhao, Jia, led several hundred of his clansmen in flight to Dai, established himself as king of Dai, and as Zhao perished, great officers gradually came to him. He joined forces with Yan and encamped at Shanggu.", idiomatic: "Prince Jia of Zhao led several hundred kinsmen to Dai, made himself king of Dai, and as Zhao fell, ministers gradually rallied to him. He joined Yan, and their combined army camped at Shanggu." },
  { zh: "4楚幽王薨，國人立其弟郝。", literal: "4 King You of Chu died; the people of the state established his younger brother Hao.", idiomatic: "4 King You of Chu died; the people set up his younger brother Hao." },
  { zh: "〔春〕，三月<ref>〔春〕三月據《通鑑》通例補</ref>，郝庶兄負芻殺之，自立。", literal: "〔Spring〕, third month<ref>〔Spring〕, third month supplemented per Zizhi Tongjian convention</ref>, Hao's elder brother by a concubine, Fuchu, killed him and established himself.", idiomatic: "〔Spring〕, third month<ref>〔Spring〕, third month supplemented per Zizhi Tongjian convention</ref>, Hao's elder half-brother Fuchu killed him and made himself ruler." },
  { zh: "5魏景湣王薨，子假立。", literal: "5 King Jingmin of Wei died; his son Jia was established.", idiomatic: "5 King Jingmin of Wei died; his son Jia succeeded." },
  { zh: "6燕太子丹怨王，欲報之，以問其傅鞠武。", literal: "6 Crown Prince Dan of Yan resented the king and wished to strike back; he asked his tutor Ju Wu.", idiomatic: "6 Crown Prince Dan of Yan hated the king and wished revenge; he consulted his tutor Ju Wu." },
  { zh: "鞠武請西約三晉，南連齊、楚，北媾匈奴以圖秦。", literal: "Ju Wu proposed allying with the Three Jins in the west, linking Qi and Chu in the south, and treating with the Xiongnu in the north to plot against Qin.", idiomatic: "Ju Wu urged an alliance with the Three Jins in the west, Qi and Chu in the south, and the Xiongnu in the north to move against Qin." },
  { zh: "太子曰：「太傅之計，曠日彌久，令人心惛然，恐不能須也。", literal: "The crown prince said, “Your plan, Tutor, drags on day after day and makes the heart grow dull; I fear one cannot wait.", idiomatic: "The crown prince said, “Tutor, your plan drags on forever and dulls the spirit—I fear we cannot wait." },
  { zh: "」頃之，將軍樊於期得罪，亡之燕；", literal: "” Before long the general Fan Yuqi offended and fled to Yan;", idiomatic: "” Soon afterward General Fan Yuqi fell from favor and fled to Yan;" },
  { zh: "太子受而舍之。", literal: "the crown prince received him and gave him lodging.", idiomatic: "the crown prince took him in and lodged him." },
  { zh: "鞠武諫曰：「夫以秦王之暴而積怒於燕，足為寒心，又況聞樊將軍之所在乎！", literal: "Ju Wu remonstrated, saying, “With the king of Qin's cruelty and his piled-up wrath against Yan, that alone is enough to chill the heart—how much more when he hears where General Fan is!", idiomatic: "Ju Wu urged, “The king of Qin is brutal and his wrath against Yan runs deep—that alone is chilling. How much worse when he learns where General Fan is!" },
  { zh: "是謂委肉當餓虎之蹊也。", literal: "This is what is called laying meat on a starving tiger's path.", idiomatic: "That is like laying meat on a starving tiger's trail." },
  { zh: "願太子疾遣樊將軍入匈奴。", literal: "I beg the crown prince quickly to send General Fan into the Xiongnu.", idiomatic: "I beg you, send General Fan quickly into the Xiongnu lands." },
  { zh: "」太子曰：「樊將軍窮困於天下，歸身於丹，是固丹命卒之時也，願更慮之！", literal: "” The crown prince said, “General Fan is destitute under Heaven and has entrusted himself to Dan; this is precisely when Dan's life reaches its end—I beg you reconsider!", idiomatic: "” The crown prince said, “General Fan is hunted everywhere and has thrown himself on Dan; this is the hour when Dan must stake his life—please think again!" },
  { zh: "」鞠武曰：「夫行危以求安，造禍以為福，計淺而怨深，乃連結一人之後交，不顧國家之大害，所謂資怨而助禍矣！", literal: "” Ju Wu said, “To seek safety by courting danger, to make blessing from disaster, to plan shallowly while enmity runs deep, and to bind up one man's late friendship without regard for the state's great harm—this is what is called feeding a grudge and aiding calamity!", idiomatic: "” Ju Wu said, “To seek safety through danger, to court disaster hoping for blessing, to plot shallowly while hatred runs deep, to tie your fate to one man's late friendship and ignore the state's ruin—that is feeding a grudge and inviting ruin!" },
  { zh: "」太子不聽。", literal: "” The crown prince would not listen.", idiomatic: "” The crown prince would not listen." },
  { zh: "太子聞衛人荊軻之賢，卑辭厚禮而請見之。", literal: "The crown prince heard that Jing Ke of Wei was worthy; with humble words and rich gifts he asked to see him.", idiomatic: "The crown prince heard that Jing Ke of Wei was a man of worth and sought him with humble words and lavish gifts." },
  { zh: "謂軻曰：「今秦已虜韓王，又舉兵南伐楚，北臨趙。", literal: "He said to Ke, “Now Qin has already captured the king of Han and is again raising troops to attack Chu in the south and press Zhao in the north.", idiomatic: "He told Ke, “Qin has already taken the king of Han and is marching south against Chu and pressing north on Zhao." },
  { zh: "趙不能支秦，則禍必至於燕。", literal: "If Zhao cannot withstand Qin, calamity is sure to reach Yan.", idiomatic: "If Zhao cannot hold Qin, disaster will reach Yan." },
  { zh: "燕小弱，數困於兵，何足以當秦！", literal: "Yan is small and weak, repeatedly harried by war—how can it suffice to face Qin!", idiomatic: "Yan is small and weak, worn down by war—how can it stand against Qin!" },
  { zh: "諸侯服秦，莫敢合從。", literal: "The feudal lords submit to Qin; none dares unite in alliance.", idiomatic: "The feudal lords bow to Qin; none dares unite against it." },
  { zh: "丹之私計愚，以為誠得天下之勇士使於秦，劫秦王，使悉反諸侯侵地，若曹沫之與齊桓公，則大善矣；", literal: "Dan's private plan is foolish: I think that if one could truly get a warrior of the realm to go to Qin, seize the king of Qin, and make him wholly restore the lands the feudal lords lost—as Cao Mo did with Duke Huan of Qi—that would be the greatest good;", idiomatic: "My private plan is crude: if we could send a true warrior of the realm to Qin, seize the king, and force him to return all seized lands—as Cao Mo did with Duke Huan of Qi—that would be best;" },
  { zh: "則不可，因而刺殺之，彼大將擅兵於外而內有亂，則君臣相疑，以其間，諸侯得合從，其破秦必矣。", literal: "if not, then stab and kill him. Their great generals hold armies abroad while within there is disorder; ruler and ministers will suspect one another. In that interval the feudal lords can unite in alliance—Qin will surely be broken!", idiomatic: "if not, stab him. With great generals holding armies abroad and turmoil within, ruler and ministers will turn on each other. In that gap the lords can unite—and Qin will fall!" },
  { zh: "唯荊卿留意焉！", literal: "I beg Commander Jing only to give this thought!", idiomatic: "Commander Jing, please weigh this!" },
  { zh: "」荊軻許之。", literal: "” Jing Ke agreed.", idiomatic: "” Jing Ke agreed." },
  { zh: "於是舍荊卿於上舍，太子日造門下，所以奉養荊軻，無所不至。", literal: "Thereupon he lodged Jing Ke in the upper guesthouse; the crown prince daily came to his door. In supporting and sustaining Jing Ke, nothing was left undone.", idiomatic: "He lodged Jing Ke in the finest quarters; the crown prince came daily to his door and spared nothing in his upkeep." },
  { zh: "及王翦滅趙，太子聞之懼，欲遣荊軻行。", literal: "When Wang Jian destroyed Zhao, the crown prince heard and was afraid; he wished to send Jing Ke on his mission.", idiomatic: "When Wang Jian destroyed Zhao, the crown prince in fear wished to send Jing Ke off at once." },
  { zh: "荊軻曰：「今行而無信，則秦未可親也。", literal: "Jing Ke said, “If I go now without credentials, Qin cannot yet be approached.", idiomatic: "Jing Ke said, “Go now without proof, and Qin will not receive us." },
  { zh: "誠得樊將軍首與燕督亢之地圖，奉獻秦王，秦王必說見臣，臣乃有以報。", literal: "If I could truly obtain General Fan's head and a map of Yan's Dukang territory and present them to the king of Qin, he will surely be pleased to receive your servant, and your servant will then have means to repay.", idiomatic: "Give me General Fan's head and a map of the Dukang region for the king of Qin—he will gladly receive me, and I will have my opening." },
  { zh: "」太子曰：「樊將軍窮困來歸丹，丹不忍也！", literal: "” The crown prince said, “General Fan came to Dan in destitution; Dan cannot bear it!", idiomatic: "” The crown prince said, “General Fan came to me in desperation—I cannot do that!" },
  { zh: "」荊軻乃私見樊於期曰：「秦之遇將軍，可謂深矣，父母宗族皆為戮沒！", literal: "” Jing Ke then privately saw Fan Yuqi and said, “Qin's treatment of you, General, may be called deep indeed—parents and clan all slaughtered and destroyed!", idiomatic: "” Jing Ke then saw Fan Yuqi in private and said, “Qin has wronged you deeply—your parents and entire clan slaughtered!" },
  { zh: "今聞購將軍首，金千斤，邑萬家，將奈何？", literal: "Now I hear a price is set on your head—a thousand jin of gold, ten thousand households in fief. What will you do?", idiomatic: "A price of a thousand jin of gold and ten thousand households is set on your head. What will you do?" },
  { zh: "」於期太息流涕曰：「計將安出？", literal: "” Fan Yuqi sighed deeply, weeping, and said, “What is your plan?", idiomatic: "” Fan Yuqi sighed through tears, “What is your plan?" },
  { zh: "」荊卿曰：「願得將軍之首以獻秦王，秦王必喜而見臣，臣左手把其袖，右手揕其胸，則將軍之仇報而燕見陵之愧除矣！", literal: "” Jing Ke said, “I wish to obtain the general's head to present to the king of Qin. He will surely be pleased to receive your servant; your servant will seize his sleeve with the left hand and stab his breast with the right—then the general's vengeance is repaid and Yan's shame of being bullied is removed!", idiomatic: "” Jing Ke said, “Give me your head for the king of Qin. He will receive me gladly; I will seize his sleeve with my left hand and stab his breast with my right—your vengeance done and Yan's humiliation ended!" },
  { zh: "」樊於期曰：「此臣之日夜切齒腐心也！", literal: "” Fan Yuqi said, “This is what your servant night and day has gnashed his teeth and rotted his heart over!", idiomatic: "” Fan Yuqi said, “That is what I have gnawed my heart over night and day!" },
  { zh: "」遂自刎。", literal: "” Thereupon he cut his own throat.", idiomatic: "” Thereupon he cut his own throat." },
  { zh: "太子聞之，奔往伏哭，然已無奈何，遂以函盛其首。", literal: "The crown prince heard, ran and threw himself down weeping over him, but nothing could be done; he then placed the head in a casket.", idiomatic: "The crown prince ran to weep over him, but it was done; he put the head in a box." },
  { zh: "太子豫求天下之利匕首，使工以藥焠之，以試人，血濡縷，人無不立死者。", literal: "The crown prince had beforehand sought the finest dagger under Heaven and had a craftsman temper it with poison. When tested on a man, blood soaked the thread and none failed to die on the spot.", idiomatic: "The crown prince had procured the finest dagger in the realm and had it poisoned. Tested on a man, blood wet the hem and none failed to die instantly." },
  { zh: "乃裝為遣荊軻，以燕勇士秦舞陽為之副，使入秦。", literal: "He then equipped Jing Ke for departure, with the Yan warrior Qin Wuyang as his aide, and sent them into Qin.", idiomatic: "He then sent Jing Ke off, with the Yan warrior Qin Wuyang as his aide, into Qin." },
  { zh: "<divclass=\"references-small\"><references/></div>", literal: "<divclass=\"references-small\"><references/></div>", idiomatic: "<divclass=\"references-small\"><references/></div>" },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
